window.CSAE=window.CSAE||{};window.CSAE.lecture=[{"week":1,"title":"HTML and CSS review; how the web works","focus":"Course orientation, HTML, CSS, HTTP and Developer Tools","duration":"2 hours","file":"Week_01_Lecture_How_the_web_works.pptx","sections":[{"kind":"outcomes","title":"Learning outcomes","tag":"LECTURE","blocks":[{"k":"list","items":[[["Review and apply semantic HTML and CSS (selectors, box model, flexbox) to structure and style a page.",false]],[["Describe the client–server model and the request–response cycle.",false]],[["Read and interpret HTTP requests, responses, headers and status codes.",false]],[["Use browser Developer Tools to inspect network traffic.",false]],[["Build a simple static, responsive page with HTML and CSS.",false]]]}],"id":"learning-outcomes"},{"kind":"divider","title":"Course orientation","tag":"SECTION","sub":"Start here. How the course, the grades and the project work.","id":"course-orientation"},{"kind":"orient","title":"About CSAE 104","tag":"ORIENT","blocks":[{"k":"p","t":"A hands-on course in full-stack web development for students who already know how to program. You begin with HTML, CSS and HTTP, learn modern JavaScript, then build a back end with Node.js, Express and MongoDB (the MERN weeks, 1 to 8). After the midterm you build the front end with React and move your data to PostgreSQL with the pg library (the PERN weeks, 10 to 16). Authentication, testing and deployment close the course."},{"k":"table","head":["Item","Details"],"rows":[["Course","CSAE 104 Web Programming"],["Type","Major course or applied elective"],["Credit","3 units: 2 hours of lecture and 3 hours of laboratory each week"],["Prerequisite","CSPC 103 Object-Oriented Programming"],["Instructor","Haydee D. Limson, MIS"],["Term","2nd Semester, Academic Year 2026-2027"]]}],"id":"about-csae-104"},{"kind":"orient","title":"Class schedule","tag":"ORIENT","blocks":[{"k":"p","t":"Find your section. Each section has two lecture hours and three laboratory hours a week."},{"k":"table","head":["Section","Lecture","Laboratory"],"rows":[["3F","MW 8:00–9:00 AM, Rm 102","MW 2:00–3:30 PM, iLab"],["3G","MW 3:30–4:30 PM, Rm 103","MW 9:30–11:00 AM, iLab"],["3B","TTh 8:00–9:00 AM, Rm 118","TTh 2:00–3:30 PM, Rm 106 Lab"],["3E","TTh 11:00 AM–12:00 PM, Rm 118","TTh 3:30–5:00 PM, Rm 106 Lab"]]}],"id":"class-schedule"},{"kind":"orient","title":"Course outcomes","tag":"ORIENT","blocks":[{"k":"p","t":"By the end of the semester you can:"},{"k":"list","items":[[["CO1. ",true],["Explain how the web works, including the client–server model, HTTP requests and responses, and status codes.",false]],[["CO2. ",true],["Apply modern JavaScript (ES6+ syntax, modules, DOM manipulation, Promises and async/await) to build interactive web pages and consume APIs.",false]],[["CO3. ",true],["Build and test RESTful web services with Node.js and Express using routing, middleware, validation and error handling.",false]],[["CO4. ",true],["Persist application data using MongoDB with Mongoose (MERN) and PostgreSQL with raw SQL through the pg library (PERN).",false]],[["CO5. ",true],["Develop React user interfaces using components, props, state, controlled forms and effects, and connect them to a back-end API.",false]],[["CO6. ",true],["Implement basic authentication and authorization, write tests, manage environment variables and deploy a full-stack application.",false]],[["CO7. ",true],["Design, build, present and defend a complete full-stack web application, the Campus Notices Board, built progressively as a semester-long capstone project.",false]]]}],"id":"course-outcomes"},{"kind":"orient","title":"How you are graded","tag":"ORIENT","blocks":[{"k":"table","head":["Part","Weight","What counts"],"rows":[["Class standing","60%","Written and hands-on exercises, laboratory deliverables, quizzes, assignments, the Campus Notices Board project and attendance"],["Major examinations","40%","Midterm examination and final examination"]]},{"k":"p","t":"Every term grade combines the two parts, and the final grade weighs the two terms:"},{"k":"code","t":"Component grade   = ((raw score / total score) * 50 + 50) * percentage\nMidterm grade     = Class standing (60%) + Midterm exam (40%)\nFinal term grade  = Class standing (60%) + Final exam (40%)\nFINAL GRADE       = 40% of Midterm grade + 60% of Final term grade","lang":"text"}],"id":"how-you-are-graded"},{"kind":"orient","title":"What you submit","tag":"ORIENT","blocks":[{"k":"list","items":[[["The Campus Notices Board, a full-stack project you build a little more of each week.",false]],[["The midterm and final examinations.",false]],[["A case study.",false]],[["Laboratory deliverables, classworks on Google Classroom, assignments, quizzes, recitation and hands-on activities.",false]]]}],"id":"what-you-submit"},{"kind":"orient","title":"Classroom policies","tag":"ORIENT","blocks":[{"k":"list","items":[[["You may be absent at most three times in a semester. A fourth absence means a failing mark.",false]],[["Late assignments and projects are not accepted without a written excuse letter.",false]],[["All programming outputs must be your own work. Plagiarism means a zero and disciplinary action.",false]],[["Use computers and devices for coursework only during class and laboratory hours.",false]],[["Follow proper laboratory etiquette and keep the computer laboratory clean.",false]],[["Take examinations on the scheduled dates. A make-up exam needs prior approval.",false]],[["Take an active part in class discussions and laboratory activities.",false]]]}],"id":"classroom-policies"},{"kind":"orient","title":"The Campus Notices Board","tag":"ORIENT","blocks":[{"k":"p","t":"One project runs through the whole semester. It starts as a static page in this week's lab and ends as a deployed full-stack application that you present and defend in Week 18."},{"k":"table","head":["Week","What you add"],"rows":[["1","A static, responsive Campus Notices page in HTML and CSS"],["2 to 3","JavaScript exercises that render and filter notices, then data fetched from a public API"],["4","A first Node program, a package.json file and a repository on GitHub"],["5 to 6","The board begins: an Express API with in-memory CRUD routes for notices (Project Checkpoint 1)"],["7 to 8","The API connected to MongoDB with Mongoose, so notices persist (Project Checkpoint 2)"],["9","Midterm examination, including a practical persistent CRUD API"],["10","PostgreSQL installed, and the notices and categories tables built with CRUD and join queries"],["11","The API moved from MongoDB to PostgreSQL with pg, using raw SQL (Project Checkpoint 3)"],["12 to 13","React components and a notice form with local state"],["14","A React list fetched from the API, with loading, error and empty states"],["15","React connected to the API: list, create, edit and delete notices, on the guided, standard or extension track"],["16","Login with hashed passwords and token checks, so only signed-in users can post"],["17","Automated tests, environment variables and deployment with a hosted PostgreSQL database"],["18","Final lab exam, then the Campus Notices Board presentation and defense"]]},{"k":"p","t":"In Week 18 your project is graded on these criteria:"},{"k":"list","items":[[["Functionality",false]],[["Code efficiency",false]],[["Code organization",false]],[["Use of web technologies",false]],[["Code readability",false]],[["Error handling",false]],[["Innovation and creativity",false]],[["Alignment with the SDGs",false]]]}],"id":"the-campus-notices-board"},{"kind":"divider","title":"Part 1: HTML and CSS review","tag":"SECTION","sub":"A refresher on the two languages every page is built from. You will use all of it in this week's lab.","id":"part-1-html-and-css-review"},{"kind":"concept","title":"A page is a tree of elements","tag":"CONCEPT","blocks":[{"k":"list","items":[[["An HTML document is text made of elements. Each element has an opening tag, content and a closing tag.",false]],[["Elements nest inside each other, so a page forms a tree: `html` contains `head` and `body`, and `body` contains everything you see.",false]],[["Attributes add details to a tag, such as `lang` on `html` or `href` on a link.",false]]]},{"k":"code","t":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Campus Notices</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n  </head>\n  <body>\n    <h1>Campus Notices</h1>\n  </body>\n</html>","lang":"xml"},{"k":"list","items":[[["The `<head>` holds information about the page: its title, its character set and the files it links to. Nothing in it is drawn on the page.",false]],[["The `<body>` holds what people see.",false]]]}],"id":"a-page-is-a-tree-of-elements"},{"kind":"concept","title":"Semantic elements","tag":"CONCEPT","blocks":[{"k":"list","items":[[["Semantic elements say what a part of the page is, not only how it looks.",false]],[["Browsers, search engines and screen readers use them to understand the page.",false]]]},{"k":"table","head":["Element","Use it for"],"rows":[["`<header>`","The introduction at the top of a page or a section"],["`<nav>`","A group of navigation links"],["`<main>`","The main content of the page, once per page"],["`<article>`","A self-contained piece, such as one notice"],["`<section>`","A themed group of content, usually with a heading"],["`<footer>`","The closing information for a page or a section"],["`<div>` and `<span>`","A plain box or a plain piece of text, when nothing more meaningful fits"]]},{"k":"code","t":"<article class=\"notice\">\n  <h2>Library hours extended</h2>\n  <p>The library stays open until 9 PM during midterm week.</p>\n</article>","lang":"xml"},{"k":"callout","t":"Use heading levels for meaning, not size: one h1 per page, then h2 for its sections, and so on. You can change the size with CSS."}],"id":"semantic-elements"},{"kind":"concept","title":"Forms","tag":"CONCEPT","blocks":[{"k":"list","items":[[["A form collects input and sends it to a server.",false]],[["Each input needs a `<label>` and a `name`. The server uses the name as the key for the value.",false]],[["The form's `method` decides how the data travels. GET puts it in the URL as a query string. POST puts it in the body of the request.",false]]]},{"k":"code","t":"<form action=\"/search\" method=\"get\">\n  <label for=\"q\">Search notices</label>\n  <input id=\"q\" name=\"q\" type=\"search\" required>\n  <select name=\"category\">\n    <option value=\"academic\">Academic</option>\n    <option value=\"events\">Events</option>\n  </select>\n  <button type=\"submit\">Search</button>\n</form>","lang":"xml"},{"k":"callout","t":"Type library, keep the first category and press Search. The browser sends this request:"},{"k":"code","t":"GET /search?q=library&category=academic HTTP/1.1\nHost: localhost:3001","lang":"http"}],"id":"forms"},{"kind":"concept","title":"CSS selectors","tag":"CONCEPT","blocks":[{"k":"list","items":[[["A CSS rule has a selector, which says what to style, and declarations, which say how.",false]],[["The selector decides which elements a rule applies to.",false]]]},{"k":"code","t":"selector {\n  property: value;\n}","lang":"css"},{"k":"table","head":["Selector","Matches","Example"],"rows":[["Type","Every element with that tag","`p`"],["Class","Elements with that class attribute","`.notice`"],["ID","The one element with that id","`#search`"],["Descendant","An element anywhere inside another","`.notice h2`"],["Child","An element directly inside another","`main > article`"],["State","An element while the mouse is over it","`a:hover`"]]}],"id":"css-selectors"},{"kind":"concept","title":"The cascade: which rule wins?","tag":"CONCEPT","blocks":[{"k":"list","items":[[["Several rules can style the same element. The browser settles the conflict like this:",false]],[["More specific wins. ",true],["An id selector beats a class selector, and a class selector beats a type selector.",false]],[["Later wins. ",true],["If two selectors are equally specific, the rule written last is used.",false]],[["Inheritance. ",true],["Some properties, such as `color` and `font-family`, pass down from the parent when no rule sets them.",false]],[["Inline `style` attributes and `!important` override all of this. Avoid both while you are learning.",false]]]}],"id":"the-cascade-which-rule-wins"},{"kind":"example","title":"Which rule wins?","tag":"WORKED EXAMPLE","blocks":[{"k":"list","items":[[["A paragraph sits inside an element with the class notice. Predict its text colour before you read the answer.",false]]]},{"k":"code","t":"p { color: black; }\n.notice p { color: navy; }\np { color: gray; }","lang":"css"},{"k":"callout","t":"The text is navy. The rule .notice p is more specific than p, so the order does not matter. Delete it, and the last p rule wins: the text turns gray."}],"id":"which-rule-wins"},{"kind":"concept","title":"The box model","tag":"CONCEPT","blocks":[{"k":"list","items":[[["Every element is a box with four layers, from the inside out: content, padding, border and margin.",false]],[["Padding is space inside the border. Margin is space outside it.",false]],[["By default `width` sets only the content, so padding and border make the box wider. Add `box-sizing: border-box` to make the width include them.",false]]]},{"k":"code","t":"* { box-sizing: border-box; }   /* optional: width now includes padding and border */\n\n.notice {\n  width: 300px;\n  padding: 20px;\n  border: 2px solid #d9e2ec;\n  margin: 16px;\n}\n/* Default (content-box): 300 + 20 + 20 + 2 + 2 = 344px wide on screen. */","lang":"css"},{"k":"callout","t":"Open Developer Tools, right-click an element, choose Inspect and look for the box diagram in the Styles panel. It shows all four layers with their sizes."}],"id":"the-box-model"},{"kind":"concept","title":"Flexbox","tag":"CONCEPT","blocks":[{"k":"list","items":[[["Flexbox lays out the children of a container in one direction, as a row or as a column.",false]],[["Set `display: flex` on the container. Its children become flex items.",false]],[["Use `gap` for the space between items, `justify-content` along the main direction and `align-items` across it.",false]]]},{"k":"code","t":".toolbar {\n  display: flex;\n  flex-direction: row;             /* row is the default; column stacks the items */\n  gap: 12px;                       /* space between the items */\n  justify-content: space-between;  /* spread the items along the main direction */\n  align-items: center;             /* centre them across it */\n}","lang":"css"},{"k":"callout","t":"In Lab 1 you use flexbox with flex-direction: column to stack the notice cards."}],"id":"flexbox"},{"kind":"concept","title":"Grid","tag":"CONCEPT","blocks":[{"k":"list","items":[[["Grid lays out items in rows and columns at the same time.",false]],[["Use it for a two-dimensional layout, such as a wall of notice cards.",false]],[["`repeat(auto-fit, minmax(240px, 1fr))` fits as many columns as the width allows.",false]]]},{"k":"code","t":".board {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 16px;\n}","lang":"css"},{"k":"callout","t":"A rule of thumb: flexbox for one direction, grid for two."}],"id":"grid"},{"kind":"concept","title":"Responsive design","tag":"CONCEPT","blocks":[{"k":"list","items":[[["A responsive page fits any screen, from a phone to a wide monitor.",false]],[["Start with the viewport tag in `<head>`: `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">`. Without it, phones pretend to be wide desktops and shrink your page.",false]],[["Use flexible sizes such as percentages, `rem` and `max-width`. Then add a media query where the layout needs to change.",false]]]},{"k":"code","t":"main {\n  max-width: 720px;   /* never wider than this, but shrinks on small screens */\n  margin: 24px auto;\n}\n\n@media (max-width: 600px) {\n  main { margin: 12px auto; }   /* applies only on screens 600px wide or narrower */\n}","lang":"css"},{"k":"callout","t":"Test it yourself. Press F12, then Ctrl+Shift+M, and choose a phone size."}],"id":"responsive-design"},{"kind":"divider","title":"Part 2: How the web works","tag":"SECTION","sub":"What happens between typing a web address and seeing a page.","id":"part-2-how-the-web-works"},{"title":"Clients and servers","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["A browser is a client.",false]],[["It asks for things.",false]],[["A server is a program on another computer that answers.",false]]]}],"extra":["Think of ordering at a carinderia: you ask for adobo and rice (the request), and the kitchen hands it over (the response). The conversation follows a fixed set of rules called HTTP, the HyperText Transfer Protocol."],"id":"clients-and-servers"},{"title":"Anatomy of a URL","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Take https://www.example.edu.ph:443/notices?page=2#latest.",false]]]},{"k":"table","head":["Part","Example","Meaning"],"rows":[["Protocol","https","The rules used to talk (HTTPS adds encryption)"],["Host","www.example.edu.ph","Which server to contact"],["Port","443","Which door on that server (often hidden)"],["Path","/notices","Which resource you want"],["Query","?page=2","Extra details for the server"],["Fragment","#latest","A spot inside the page, handled only by the browser"]]}],"id":"anatomy-of-a-url"},{"title":"The journey of one page","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["The browser asks DNS, the internet's phone book, for the server's IP address.",false]],[["The browser opens a connection to that address.",false]],[["The browser sends an HTTP request.",false]],[["The server sends back an HTTP response.",false]],[["The browser reads the HTML, then sends more requests for the CSS, JavaScript and images it finds.",false]],[["The browser draws the page.",false]]]}],"id":"the-journey-of-one-page"},{"title":"Reading three addresses","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Take the parts you just learned and apply them to addresses you will meet in this course.",false]],[["For each, name the protocol, host, port, path and query.",false]]]},{"k":"table","head":["Address","Protocol","Host","Port","Path","Query"],"rows":[["https://www.dmmmsu.edu.ph/news?page=2","https","www.dmmmsu.edu.ph","443 (hidden, the default for https)","/news","page=2"],["http://localhost:3001/api/notices/5","http","localhost (your own computer)","3001","/api/notices/5","none"],["http://localhost:5173/index.html#top","http","localhost","5173","/index.html","none (#top is a fragment, which the browser keeps to itself and never sends)"]]},{"k":"list","items":[[["Notice that localhost:3001 and localhost:5173 are the same computer but different \"doors\", so they are different servers.",false]],[["You will use exactly this idea from Week 14, when your React page on port 5173 talks to your API on port 3001.",false]]]}],"id":"reading-three-addresses"},{"title":"What a request and a response look like","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["They are plain text.",false]]]},{"k":"code","t":"GET /notices HTTP/1.1\nHost: www.example.edu.ph\nAccept: text/html","lang":"http"},{"k":"code","t":"HTTP/1.1 200 OK\nContent-Type: text/html; charset=utf-8\nContent-Length: 1842\n\n<!doctype html>\n<html>...</html>","lang":"http"},{"k":"callout","t":"The first line of a request holds the method and the path. The first line of a response holds the status code. Lines like Content-Type are headers: small labelled notes about the message. After a blank line comes the body, which is the actual content."}],"id":"what-a-request-and-a-response-look-like"},{"title":"One request, two possible responses","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Suppose your browser asks for the notices page, and later for a page that does not exist.",false]],[["This is what travels over the wire (shortened).",false]]]},{"k":"code","t":"GET /index.html HTTP/1.1\nHost: localhost:3001\nAccept: text/html\n\nHTTP/1.1 200 OK\nContent-Type: text/html; charset=utf-8\nContent-Length: 612","lang":"http"},{"k":"code","t":"\n<!DOCTYPE html><html> ... the notices page ... </html>","lang":"xml"},{"k":"code","t":"GET /nope.html HTTP/1.1\nHost: localhost:3001\n\nHTTP/1.1 404 Not Found\nContent-Type: text/html; charset=utf-8\n\nCannot GET /nope.html","lang":"http"},{"k":"list","items":[[["Read the first line of each request: the method (GET) and the path (/index.html or /nope.html).",false]],[["Read the first line of each response: the status code (200 or 404).",false]]]}],"extra":["The only difference between success and failure is the path the client asked for and the code the server chose. The Content-Type header tells the browser what to do with the body: draw it as a page."],"id":"one-request-two-possible-responses"},{"title":"Methods, the verbs of the web","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["You will meet these again in Week 6.",false]]]},{"k":"table","head":["Method","Plain meaning"],"rows":[["GET","Give me this"],["POST","Here is something new, please create it"],["PUT or PATCH","Here is an updated version, please change it"],["DELETE","Please remove this"]]}],"id":"methods-the-verbs-of-the-web"},{"title":"Status codes tell you how it went","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["They come in families.",false]]]},{"k":"table","head":["Range","Meaning","Example"],"rows":[["2xx","Success","200 OK, 201 Created"],["3xx","Look somewhere else","301 Moved Permanently"],["4xx","The request has a problem","404 Not Found, 400 Bad Request"],["5xx","The server has a problem","500 Internal Server Error"]]}],"id":"status-codes-tell-you-how-it-went"},{"title":"Your best friend: the Network tab","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Open any site, press F12, choose Network, and reload.",false]],[["Click a request to see its headers, response and timing.",false]],[["You will use this tab every single week.",false]]]}],"id":"your-best-friend-the-network-tab"},{"title":"Tracing one page load","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["You type http://localhost:3001/index.html for your notices page.",false]],[["Open the Network tab first and you should see something like this:",false]]]},{"k":"table","head":["#","Request","Status","Why it happened"],"rows":[["1","GET /index.html","200","You asked for the page"],["2","GET /styles.css","200","The HTML contains <link rel=\"stylesheet\" href=\"styles.css\">, so the browser asked for it"],["3","GET /favicon.ico","404","The browser asks for a tab icon on its own, and you did not make one (harmless)"]]},{"k":"list","items":[[["Three requests for one page.",false]],[["Now try an experiment: misspell styles.css as style.css in the <link> tag and reload.",false]],[["Row 2 becomes GET /style.css with status 404, and the page loses its styling.",false]]]}],"extra":["The Network tab tells you exactly which file failed, which is why you open it first when something looks wrong."],"id":"tracing-one-page-load"}],"quiz":[{"q":"Which element best marks up one self-contained notice on a page?","options":["article, because the notice makes sense on its own","span, because it groups a short piece of inline text","div, because it tells screen readers what the box means","footer, because the notice sits at the end of the page"],"answer":0},{"q":"A box has width 300px, padding 20px and a 2px border, with the default box-sizing. How wide is it on screen?","options":["300px, because the width always includes the padding","320px, because the border is drawn inside the width","344px, because padding and border are added to the width","340px, because only the padding is added to the width"],"answer":2},{"q":"A p rule and a .notice p rule disagree about colour, in the same file. Which one wins?","options":["p, because simple rules are applied before the others",".notice p, because its selector is more specific","Neither, because the browser mixes the two colours","Whichever comes last, because order beats everything"],"answer":1},{"q":"Which part of a URL names the server to contact?","options":["The host, such as www.example.edu.ph in the address","The query, such as ?page=2 at the end of the path","The fragment, such as #latest after the full address","The protocol, such as https at the start of the link"],"answer":0},{"q":"A response begins with HTTP/1.1 404 Not Found. What does it mean?","options":["The server crashed while it was running your own code","The server could not find the thing the client asked for","The client sent data that the server refused to accept","The client must send its request again to another server"],"answer":1},{"q":"Which method asks the server to create a new resource?","options":["GET, because it carries information to the server","POST, because it sends new data for the server","DELETE, because it removes an item from the list","HEAD, because it only asks about the first lines"],"answer":1},{"q":"In your own words, list the steps from typing a URL to seeing a page.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Why does a browser make several requests to show one page?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Fielding, R. T. (2000). Architectural styles and the design of network-based software architectures [Doctoral dissertation, University of California, Irvine]. https://ics.uci.edu/~fielding/pubs/dissertation/top.htm","Fielding, R., Nottingham, M., & Reschke, J. (2022). HTTP semantics (RFC 9110). Internet Engineering Task Force. https://www.rfc-editor.org/rfc/rfc9110","Google. (n.d.). Network features reference. Chrome for Developers. https://developer.chrome.com/docs/devtools/network/reference","Limson, H. D. (2026). Web programming: From MERN to PERN, module by week (1st ed.). Don Mariano Marcos Memorial State University, South La Union Campus. (Chapter 1: How the web works)","Limson, H. D. (2026). CSAE 104 Web programming: Laboratory manual (Student ed.). Don Mariano Marcos Memorial State University, South La Union Campus. (Lab 1)","MDN Contributors. (n.d.-a). An overview of HTTP. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/Overview","MDN Contributors. (n.d.-b). HTTP request methods. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/Methods","MDN Contributors. (n.d.-c). HTTP response status codes. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/Status","MDN Contributors. (n.d.-d). Learn web development. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Learn_web_development","MDN Contributors. (n.d.-e). HTML elements reference. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTML/Element","MDN Contributors. (n.d.-f). Introduction to the CSS box model. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_box_model/Introduction_to_the_CSS_box_model","MDN Contributors. (n.d.-g). Basic concepts of flexbox. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_flexible_box_layout/Basic_concepts_of_flexbox","MDN Contributors. (n.d.-h). Using media queries. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_media_queries/Using_media_queries"],"refsIntro":null,"syllabus":{"label":"Week 1","hours":"5 hours: lecture 2, laboratory 3","outcomes":["Review and apply semantic HTML and CSS (selectors, box model, flexbox) to structure and style a page.","Describe the client–server model and the request–response cycle.","Read and interpret HTTP requests, responses, headers and status codes.","Use browser Developer Tools to inspect network traffic.","Build a simple static, responsive page with HTML and CSS."],"topics":{"lecture":["HTML review: document structure, semantic elements and forms","CSS review: selectors, the cascade, the box model, flexbox, grid and responsive design","Client–server model and the request–response cycle","URLs, DNS, browsers and servers","HTTP methods, headers and status codes","Inspecting traffic with browser Developer Tools","Course orientation and Campus Notices Board overview"],"laboratory":["Set up VS Code, Git and browser Developer Tools","Build a static, responsive HTML/CSS page (semantic HTML, flexbox)","Inspect an HTTP request and response in the Network tab"]},"methods":["Interactive lecture","Visual demonstration (DevTools Network tab)","Guided practice (HTML/CSS review and warm-up)","Flipped learning (pre-reading)"],"resources":["VS Code; Git; Chrome, Edge or Firefox with Developer Tools","Limson (2026), Ch. 1 (How the web works)","Limson (2026), Laboratory manual, Lab 1","Fielding et al. (2022), RFC 9110 (selected sections on HTTP semantics)","Mozilla Developer Network (n.d.), Learn web development: HTML, CSS and HTTP guides","Course slides (HTML and CSS review; How the web works)"],"assessment":["Written quiz: HTML/CSS review, HTTP, requests and responses","Recitation: trace what happens when a URL is opened","Lab 1 output: responsive HTML/CSS page with a Network-tab screenshot"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"Understanding how the web works is the entry-point competency for every web and ICT career."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.c: Significantly increase access to information and communications technology.","link":"The web is the delivery channel through which access to ICT and information reaches communities."}]},"pptxNote":"The slide file is the earlier version. This page follows the revised syllabus.","slideCount":24,"pptx":"downloads/lecture/Week_01_Lecture_How_the_web_works.pptx"},{"week":2,"title":"Modern JavaScript","focus":"ES6, modules and the DOM","duration":"2 hours","file":"Week_02_Lecture_Modern_JavaScript.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["Write modern JavaScript using ES6+ syntax and modules.",false]],[["Select and manipulate DOM elements and respond to events.",false]]]}],"id":"learning-outcomes"},{"title":"Variables","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Use const by default.",false]],[["Use let only when the value must change.",false]],[["Avoid var: it has surprising scoping rules.",false]]]},{"k":"code","t":"const school = \"DMMMSU\";\nlet votes = 0;\nvotes = votes + 1;","lang":"javascript"}],"id":"variables"},{"title":"Const, let and what the error looks like","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"const appName = \"Campus Notices\";\nlet unread = 3;\n\nunread = unread + 1;      // fine: let can change\nconsole.log(unread);       // 4\n\nappName = \"Other\";         // TypeError: Assignment to constant variable.","lang":"javascript"},{"k":"callout","t":"The last line stops the program and prints the error. That is useful: it tells you that you tried to change something you promised would not change. One more detail that surprises people: const stops you re-assigning the variable, not changing what is inside an object or array."},{"k":"code","t":"const notices = [];\nnotices.push({ id: 1 });   // allowed: the array itself is modified\nconsole.log(notices);      // [ { id: 1 } ]\nnotices = [];              // TypeError: the variable cannot be re-assigned","lang":"javascript"},{"k":"callout","t":"In React (Week 13) you will avoid even changing the contents, and build a new array instead."}],"id":"const-let-and-what-the-error-looks-like"},{"title":"Arrow functions and template literals","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Arrow functions are a shorter way to write a function.",false]],[["Template literals use backticks and let you place values inside text with ${...}.",false]]]},{"k":"code","t":"const total = (price, qty) => price * qty;\nconst label = (name, price) => `${name} costs PHP ${price}`;\n\nconsole.log(label(\"Ballpen\", total(12, 3))); // Ballpen costs PHP 36","lang":"javascript"}],"id":"arrow-functions-and-template-literals"},{"title":"From a function declaration to an arrow function","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Here is one function written four ways, each a little shorter.",false]],[["They all do the same thing.",false]]]},{"k":"code","t":"function shortTitle(title) {            // 1. a normal function\n  return title.slice(0, 10) + \"...\";\n}\n\nconst shortTitle = function (title) {   // 2. a function stored in a variable\n  return title.slice(0, 10) + \"...\";\n};","lang":"javascript"},{"k":"code","t":"const shortTitle = (title) => {         // 3. an arrow function\n  return title.slice(0, 10) + \"...\";\n};\n\nconst shortTitle = (title) => title.slice(0, 10) + \"...\"; // 4. one expression, no braces, no return\n\nconsole.log(shortTitle(\"Library hours extended\")); // \"Library h...\"","lang":"javascript"},{"k":"callout","t":"When the body is a single expression, the arrow function returns it automatically. Add a template literal and you can build a sentence:"},{"k":"code","t":"const line = (n) => `#${n.id}: ${shortTitle(n.title)}`;\nconsole.log(line({ id: 7, title: \"Programming contest\" })); // \"#7: Programming...\"","lang":"javascript"}],"id":"from-a-function-declaration-to-an-arrow-function"},{"title":"Destructuring, spread and rest","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["These let you take objects and arrays apart, and build new ones, without changing the originals.",false]],[["You will rely on this heavily in React.",false]]]},{"k":"code","t":"const notice = { id: 1, title: \"Enrollment reminder\", pinned: false };\nconst { title, pinned } = notice;          // destructuring\nconst updated = { ...notice, pinned: true }; // spread: a copy with one change","lang":"javascript"}],"id":"destructuring-spread-and-rest"},{"title":"Array methods that replace loops","tag":"CONCEPT","kind":"concept","blocks":[{"k":"table","head":["Method","What it does","Returns"],"rows":[["map","Transforms every item","A new array of the same length"],["filter","Keeps items that pass a test","A new, possibly shorter array"],["find","Gets the first item that passes","One item, or undefined"],["reduce","Combines all items into one value","A single value"]]},{"k":"code","t":"const items = [\n  { name: \"Rice\", price: 55 },\n  { name: \"Egg\", price: 9 },\n  { name: \"Soy sauce\", price: 18 },\n];\n\nconst names = items.map((i) => i.name);","lang":"javascript"},{"k":"code","t":"const cheap = items.filter((i) => i.price < 20);\nconst total = items.reduce((sum, i) => sum + i.price, 0); // 82","lang":"javascript"}],"id":"array-methods-that-replace-loops"},{"title":"Following the data through map, filter, reduce and spread","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Start with this array and read each result before you look at the next line.",false]]]},{"k":"code","t":"const notices = [\n  { id: 1, title: \"Library hours\",   pinned: true,  views: 40 },\n  { id: 2, title: \"Enrollment\",      pinned: false, views: 25 },\n  { id: 3, title: \"Programming cup\", pinned: false, views: 10 },\n];\n\nnotices.map((n) => n.title);\n// [\"Library hours\", \"Enrollment\", \"Programming cup\"]   same length, new shape","lang":"javascript"},{"k":"code","t":"\nnotices.filter((n) => n.pinned);\n// [ { id: 1, ... } ]                                     only the items that pass\n\nnotices.reduce((sum, n) => sum + n.views, 0);\n// 75                                                     many items become one value\n\nconst updated = { ...notices[1], pinned: true };\nconsole.log(updated.pinned);     // true\nconsole.log(notices[1].pinned);  // false  the original did not change","lang":"javascript"},{"k":"list","items":[[["The last two lines are the important ones.",false]],[["Spread made a copy with one field changed, and the original stayed the same. map, filter and reduce also return new values and leave notices alone.",false]]]}],"extra":["React depends on this habit: in Week 13 you will update state by building a new array, never by editing the old one."],"id":"following-the-data-through-map-filter-reduce-and"},{"title":"Modules","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Real programs are split across files.",false]],[["A file exports what others may use, and another file imports it.",false]]]},{"k":"code","t":"// notices.js\nexport const notices = [{ id: 1, title: \"Library hours extended\" }];\nexport function titles() {\n  return notices.map((n) => n.title);\n}","lang":"javascript"},{"k":"code","t":"// main.js\nimport { titles } from \"./notices.js\";\nconsole.log(titles());","lang":"javascript"},{"k":"callout","t":"To use modules in a browser, load the script with <script type=\"module\" src=\"main.js\"></script>."}],"id":"modules"},{"title":"Two files sharing data with modules","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"// notices.js\nexport const notices = [\n  { id: 1, title: \"Library hours extended\" },\n  { id: 2, title: \"Enrollment reminder\" },\n];\n\nexport function findById(id) {\n  return notices.find((n) => n.id === id);\n}","lang":"javascript"},{"k":"code","t":"// main.js\nimport { notices, findById } from \"./notices.js\";\n\nconsole.log(notices.length);      // 2\nconsole.log(findById(2).title);   // \"Enrollment reminder\"","lang":"javascript"},{"k":"code","t":"<script type=\"module\" src=\"main.js\"></script>","lang":"xml"},{"k":"callout","t":"If you forget type=\"module\", the console shows Uncaught SyntaxError: Cannot use import statement outside a module. If you open index.html by double-clicking it, the browser blocks the import with a CORS error; open it with the VS Code Live Server extension instead."}],"id":"two-files-sharing-data-with-modules"},{"title":"The DOM","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["The browser turns your HTML into a tree of objects called the Document Object Model.",false]],[["JavaScript can find, change, add and remove those objects.",false]]]},{"k":"code","t":"const list = document.querySelector(\"#notice-list\");\nconst li = document.createElement(\"li\");\nli.textContent = \"Last day to drop subjects is Friday\";\nlist.appendChild(li);\n\ndocument.querySelector(\"#add-btn\").addEventListener(\"click\", () => {\n  console.log(\"Button clicked\");","lang":"javascript"},{"k":"code","t":"});","lang":"text"}],"id":"the-dom"},{"title":"Render a list and filter it as you type","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"<input id=\"search\" placeholder=\"Search notices\" />\n<ul id=\"notice-list\"></ul>","lang":"xml"},{"k":"code","t":"import { notices } from \"./notices.js\";\n\nconst list = document.querySelector(\"#notice-list\");\nconst search = document.querySelector(\"#search\");\n\nfunction render(items) {\n  list.innerHTML = \"\";                       // clear the old list\n  items.forEach((n) => {\n    const li = document.createElement(\"li\"); // make an element","lang":"javascript"},{"k":"code","t":"    li.textContent = n.title;                // fill it (safe from injected HTML)\n    list.appendChild(li);                    // put it in the page\n  });\n}\n\nsearch.addEventListener(\"input\", () => {\n  const term = search.value.toLowerCase();\n  render(notices.filter((n) => n.title.toLowerCase().includes(term)));\n});\n\nrender(notices); // first draw","lang":"javascript"},{"k":"list","items":[[["Trace what happens when you type lib.",false]],[["After l, the input event fires, filter keeps every title containing l, and render redraws.",false]],[["After li and lib it narrows again until only \"Library hours extended\" remains.",false]]]}],"extra":["Clear the box and the whole list returns, because an empty string is contained in every title. The pattern is always the same: change the data, then draw again. React automates the redrawing step."],"id":"render-a-list-and-filter-it-as-you-type"}],"quiz":[{"q":"What does filter return?","options":["A new array holding only the items that pass the test","The first item in the array that passes the given test","The same array with the failing items removed inside it","A single value that combines all of the items together"],"answer":0},{"q":"What is the value of updated.pinned after const updated = { ...notice, pinned: true }?","options":["true, and the original notice object is left unchanged","true, and the original notice object is changed as well","false, because spread copies the old values over new ones","undefined, because spread cannot be used with an object"],"answer":0},{"q":"Why do we write <script type=\"module\">?","options":["So the file can use import and export between other files","So the browser will run the script before the page loads","So the script is hidden from the browser developer tools","So the script will run faster than a normal script does"],"answer":0},{"q":"Write one line of code that adds a new <li> to the list #notice-list.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Explain the difference between const and let in one sentence.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Flanagan, D. (2020). JavaScript: The definitive guide (7th ed.). O’Reilly Media.","Haverbeke, M. (2018). Eloquent JavaScript: A modern introduction to programming (3rd ed.). No Starch Press. https://eloquentjavascript.net","Kantor, I. (n.d.). The modern JavaScript tutorial. https://javascript.info/","Limson, H. D. (2026). Web programming: From MERN to PERN, module by week (1st ed.). Don Mariano Marcos Memorial State University, South La Union Campus. (Chapter 2: Modern JavaScript)","MDN Contributors. (n.d.-a). Array. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array","MDN Contributors. (n.d.-b). Destructuring assignment. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Destructuring_assignment","MDN Contributors. (n.d.-c). Introduction to the DOM. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model/Introduction","MDN Contributors. (n.d.-d). JavaScript guide. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide","MDN Contributors. (n.d.-e). JavaScript reference. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference","MDN Contributors. (n.d.-f). Spread syntax (...). MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Spread_syntax"],"refsIntro":null,"syllabus":{"label":"Weeks 2 to 3","hours":"Weeks 2 and 3 share one plan: 10 hours in all (lecture 4, laboratory 6)","outcomes":["Write modern JavaScript using ES6+ syntax and modules.","Select and manipulate DOM elements and respond to events.","Explain callbacks, Promises and async/await and use them correctly.","Fetch JSON from a public API and display it with loading and error handling."],"outcomesNote":"Outcomes 1 and 2 are the focus of Week 2. Outcomes 3 and 4 continue in Week 3.","topics":{"lecture":["ES6+: let/const, arrow functions, destructuring, template literals","Modules (import/export)","DOM selection, events and manipulation","Callbacks, Promises and async/await","Fetch API, JSON and error handling with try/catch"],"laboratory":["Complete ES6 and DOM exercises","Fetch and display data from a public API","Handle loading and error cases"]},"methods":["Lecture with live coding","Predict-the-output activity","Problem-based learning (public API task)","Paired programming","Individual lab practice"],"resources":["VS Code; browser Developer Tools; a public REST API","Limson (2026), Chaps. 2–3 (Modern JavaScript; Asynchronous JavaScript)","Limson (2026), Laboratory manual, Labs 2–3","Flanagan (2020), chapters on modules and asynchronous JavaScript","Haverbeke (2018), chapters on the DOM and asynchronous programming","Mozilla Developer Network (n.d.), JavaScript guide"],"assessment":["Quiz 1: ES6 and DOM (Week 2)","Lab 2 output: JavaScript exercises (Week 2)","Quiz 2: Promises and async/await (Week 3)","Lab 3 output: public-API fetch page (Week 3)","Google Classroom activity: debug an async function (Week 3)"],"sdg":[{"goal":"SDG 4: Quality Education","target":"Target 4.4: By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship.","link":"JavaScript is the core language of the web and a high-demand skill for ICT employment."},{"goal":"SDG 9: Industry, Innovation and Infrastructure","target":"Target 9.5: Enhance scientific research and upgrade technological capabilities.","link":"Consuming open APIs trains students to build on existing digital infrastructure and innovate on top of it."}]},"pptxNote":"The slide file is the earlier version. This page follows the revised syllabus.","slideCount":32,"pptx":"downloads/lecture/Week_02_Lecture_Modern_JavaScript.pptx"},{"week":3,"title":"Asynchronous JavaScript","focus":"promises, async/await, fetch and JSON","duration":"2 hours","file":"Week_03_Lecture_Asynchronous_JavaScript.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can explain why some code must wait, use promises and async/await, call an API with fetch, and handle errors properly.",false]]]}],"id":"learning-outcomes"},{"title":"Why waiting matters","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Fetching data from another computer takes time.",false]],[["If JavaScript stopped everything to wait, the page would freeze.",false]],[["So JavaScript starts the slow task, carries on with other work, and comes back when the result is ready.",false]]]},{"k":"code","t":"console.log(\"1. order placed\");\nsetTimeout(() => console.log(\"3. drink ready\"), 1000);\nconsole.log(\"2. waiting at the table\");\n// prints 1, then 2, then 3","lang":"javascript"}],"extra":["Picture a milk tea shop: you order, get a buzzer, and sit down. You do not stand at the counter blocking everyone behind you."],"id":"why-waiting-matters"},{"title":"Predict the order","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Before you run this, write down the order you expect.",false]]]},{"k":"code","t":"console.log(\"1. ordering coffee\");\nsetTimeout(() => console.log(\"3. coffee ready\"), 1000);\nconsole.log(\"2. reading a book while waiting\");","lang":"javascript"},{"k":"callout","t":"The output is:"},{"k":"code","t":"1. ordering coffee\n2. reading a book while waiting\n3. coffee ready","lang":"text"},{"k":"list","items":[[["JavaScript does not stop at line 2 to wait.",false]],[["It hands the timer to the browser, carries on, and comes back to the callback when the second has passed.",false]],[["A fetch to a server works the same way:",false]]]}],"extra":["JavaScript sends the request, keeps the page alive, and runs your code when the answer arrives. Promises and async/await are tidy ways to say \"do this when the answer is back\"."],"id":"predict-the-order"},{"title":"Promises","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["A promise is an object that stands for a result that will arrive later.",false]],[["It is in one of three states: pending, fulfilled (success) or rejected (failure).",false]]]},{"k":"code","t":"fetch(\"https://jsonplaceholder.typicode.com/posts/1\")\n  .then((res) => res.json())\n  .then((post) => console.log(post.title))\n  .catch((err) => console.error(\"Something went wrong\", err));","lang":"javascript"}],"id":"promises"},{"title":"Async and await","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["The same logic reads like normal top-to-bottom code.",false]],[["Mark a function async, then await each promise inside it.",false]]]},{"k":"code","t":"async function loadPost(id) {\n  try {\n    const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`);\n    if (!res.ok) {\n      throw new Error(`Server answered ${res.status}`);\n    }\n    const post = await res.json();\n    return post;","lang":"javascript"},{"k":"code","t":"  } catch (err) {\n    console.error(err.message);\n  }\n}","lang":"javascript"},{"k":"callout","t":"Two details that trip up almost everyone:"},{"k":"list","items":[[["fetch only rejects when the network fails. A 404 or 500 still resolves, so you must check res.ok yourself.",false]],[["res.json() is also asynchronous, so it needs its own await.",false]]]}],"id":"async-and-await"},{"title":"The fetch that \"succeeds\" with a 404","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"async function load(url) {\n  const res = await fetch(url);\n  console.log(res.status, res.ok);\n}\n\nload(\"https://jsonplaceholder.typicode.com/posts/1\");   // 200 true\nload(\"https://jsonplaceholder.typicode.com/posts/9999\"); // 404 false","lang":"javascript"},{"k":"callout","t":"Both calls resolve without throwing, so a try/catch alone would never notice the 404. The fix is one extra line:"},{"k":"code","t":"const res = await fetch(url);\nif (!res.ok) throw new Error(`Server answered ${res.status}`); // now the catch block runs\nconst data = await res.json();","lang":"javascript"},{"k":"callout","t":"Without that line, res.json() would happily read the 404's body, and your page would show an empty or broken card with no error message. Many students lose an hour to this bug, so check res.ok every time."}],"id":"the-fetch-that-succeeds-with-a-404"},{"title":"JSON","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["JavaScript Object Notation is the text format that APIs use to send data.",false]],[["It looks like a JavaScript object, with stricter rules: keys in double quotes, no comments, no trailing commas.",false]]]},{"k":"table","head":["Direction","Function","Example"],"rows":[["Text to object","JSON.parse","JSON.parse('{\"id\":1}') gives { id: 1 }"],["Object to text","JSON.stringify","JSON.stringify({ id: 1 }) gives '{\"id\":1}'"]]}],"id":"json"},{"title":"JSON going in and coming out","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"const notice = { title: \"Library hours\", pinned: true, views: 40 };\n\nconst text = JSON.stringify(notice);\nconsole.log(text);\n// '{\"title\":\"Library hours\",\"pinned\":true,\"views\":40}'   a string, ready to send\nconsole.log(typeof text);    // \"string\"\n\nconst back = JSON.parse(text);\nconsole.log(back.title);     // \"Library hours\"\nconsole.log(typeof back);    // \"object\"","lang":"javascript"},{"k":"callout","t":"The network can only carry text, so objects are turned into a string on the way out (stringify) and back into an object on the way in (parse). Strict rules apply. This text is invalid JSON, and JSON.parse would throw:"},{"k":"code","t":"{ title: 'Library hours', pinned: true, }","lang":"text"},{"k":"callout","t":"It has unquoted keys, single quotes and a trailing comma. The valid version is {\"title\":\"Library hours\",\"pinned\":true}."}],"id":"json-going-in-and-coming-out"},{"title":"Sending data","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["A GET needs only a URL.",false]],[["To send data, choose the method, set the header and stringify the body.",false]],[["You will do exactly this in Week 15.",false]]]},{"k":"code","t":"const res = await fetch(\"https://jsonplaceholder.typicode.com/posts\", {\n  method: \"POST\",\n  headers: { \"Content-Type\": \"application/json\" },\n  body: JSON.stringify({ title: \"Hello\", body: \"First post\", userId: 1 }),\n});","lang":"javascript"}],"id":"sending-data"},{"title":"A complete, careful fetch","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["This function puts the whole lecture together: it waits, checks the status, reads JSON, and tells the user what is going on.",false]]]},{"k":"code","t":"async function loadPosts() {\n  const status = document.querySelector(\"#status\");\n  status.textContent = \"Loading...\";\n  try {\n    const res = await fetch(\"https://jsonplaceholder.typicode.com/posts\");\n    if (!res.ok) throw new Error(`Server answered ${res.status}`);\n    const posts = await res.json();\n    status.textContent = \"\";\n    console.log(posts.length);       // 100","lang":"javascript"},{"k":"code","t":"    console.log(posts[0].title);     // the first post's title\n  } catch (err) {\n    status.textContent = \"Could not load posts. Please try again.\";\n    console.error(err.message);\n  }\n}","lang":"javascript"},{"k":"callout","t":"Three things can happen, and you should see each one on purpose in the lab:"},{"k":"table","head":["Situation","What the user sees","Console"],"rows":[["Everything works","\"Loading...\" then the posts","100 and a title"],["Wrong address (/postz)","\"Could not load posts. Please try again.\"","Server answered 404"],["Wi-Fi off","The same friendly message","Failed to fetch"]]},{"k":"list","items":[[["Notice that the user never sees the technical message.",false]],[["Developers read the console, and users read the page.",false]]]}],"id":"a-complete-careful-fetch"}],"quiz":[{"q":"Why does fetch need await res.json() and not just res.json()?","options":["Reading the body takes time, so it returns a promise","Without it the body is sent back to the server again","The server would refuse the request without the await","It turns the data from plain text into a string value"],"answer":0},{"q":"A server answers 404. What does fetch do?","options":["It resolves normally, so you must check the res.ok flag","It rejects at once, so the catch block always runs next","It retries the same request until the server finds a page","It stops the program, so the page needs to be reloaded"],"answer":0},{"q":"Which line is valid JSON?","options":["{\"title\": \"Library hours\", \"pinned\": true}","{title: \"Library hours\", pinned: true,}","{'title': 'Library hours', 'pinned': true}","{\"title\": \"Library hours\", // pinned\": true}"],"answer":0},{"q":"Write the three options you pass to fetch to send a JSON POST.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"In your own words, why does asynchronous code keep a web page responsive?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Kantor, I. (n.d.). Promises, async/await. In The modern JavaScript tutorial. https://javascript.info/async","MDN Contributors. (n.d.-a). Asynchronous JavaScript. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/Asynchronous","MDN Contributors. (n.d.-b). Using the Fetch API. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch","MDN Contributors. (n.d.-c). Working with JSON. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/JSON","typicode. (n.d.). JSONPlaceholder: Free fake and reliable API for testing and prototyping. https://jsonplaceholder.typicode.com/"],"refsIntro":null,"slideCount":24,"pptx":"downloads/lecture/Week_03_Lecture_Asynchronous_JavaScript.pptx"},{"week":4,"title":"Node.js and npm","focus":"running JavaScript outside the browser","duration":"2 hours","file":"Week_04_Lecture_Node_js_and_npm.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can run JavaScript with Node, use built-in modules, create a project with npm, and explain what package.json and node_modules are for.",false]]]}],"id":"learning-outcomes"},{"title":"What Node is","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Node.js lets you run JavaScript on your computer or a server, not only inside a browser.",false]],[["It uses the same engine as Chrome (V8) but adds tools a browser does not have, such as reading files and listening for network requests.",false]]]},{"k":"code","t":"node -v\nnode hello.js","lang":"bash"},{"k":"code","t":"// hello.js\nconsole.log(\"Hello from Node\");\nconsole.log(\"Arguments:\", process.argv.slice(2));","lang":"javascript"},{"k":"callout","t":"Run node hello.js Maria Juan and you will see the two names in the list. process.argv holds everything typed on the command line."}],"extra":["This is the \"N\" in MERN, and it is why we can use one language on both sides of a web app."],"id":"what-node-is"},{"title":"No document, no window","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["There is no page in Node, so browser objects like document do not exist.",false]],[["In their place you get Node's own objects, such as process.",false]]]}],"id":"no-document-no-window"},{"title":"What process.argv really holds","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"// hello.js\nconsole.log(process.argv);\nconst names = process.argv.slice(2); // skip the first two entries\nconsole.log(`Hello, ${names.join(\" and \")}!`);","lang":"javascript"},{"k":"callout","t":"Run node hello.js Maria Juan and you see:"},{"k":"code","t":"[ '/usr/bin/node', '/home/you/hello.js', 'Maria', 'Juan' ]\nHello, Maria and Juan!","lang":"text"},{"k":"list","items":[[["The first entry is the Node program, the second is your script, and everything after that is what you typed.",false]],[["That is why the code uses slice(2).",false]]]}],"extra":["This is the whole idea behind node cli.js add \"Title\" \"Message\" in the lab: the words after the file name arrive as an array, and your program decides what they mean. Run it with no names and you get Hello, !, a good reminder to check for missing input."],"id":"what-process-argv-really-holds"},{"title":"Built-in modules","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Node ships with useful modules.",false]],[["You load them with require.",false]]]},{"k":"table","head":["Module","What it is for"],"rows":[["fs","Reading and writing files"],["path","Building file paths that work on every operating system"],["os","Information about the computer"],["http","Creating a basic web server"]]},{"k":"code","t":"const fs = require(\"fs\");\nconst path = require(\"path\");\n\nconst file = path.join(__dirname, \"notices.json\");\nconst notices = JSON.parse(fs.readFileSync(file, \"utf8\"));\nconsole.log(`There are ${notices.length} notices`);","lang":"javascript"}],"id":"built-in-modules"},{"title":"The same module in both styles","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"// CommonJS (what this course uses on the server)\n// notices.js\nconst notices = [{ id: 1, title: \"Library hours\" }];\nmodule.exports = { notices };\n\n// app.js\nconst { notices } = require(\"./notices\");\nconsole.log(notices.length); // 1","lang":"javascript"},{"k":"code","t":"// ES modules (what the browser and React use)\n// notices.js\nexport const notices = [{ id: 1, title: \"Library hours\" }];\n\n// app.js\nimport { notices } from \"./notices.js\";\nconsole.log(notices.length); // 1","lang":"javascript"},{"k":"list","items":[[["The behaviour is identical; only the words change.",false]],[["If you mix them up in a CommonJS project, Node prints SyntaxError:",false]],[["Cannot use import statement outside a module.",false]]]}],"extra":["If you use require in a project that is set to ES modules, you get ReferenceError: require is not defined. Seeing either message should tell you to check which style your file is using."],"id":"the-same-module-in-both-styles"},{"title":"Two module styles","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Older Node code uses CommonJS (require and module.exports).",false]],[["Newer code uses ES modules (import and export), the style you met in Week 2.",false]],[["Both work.",false]]]},{"k":"code","t":"// CommonJS\nconst express = require(\"express\");\nmodule.exports = { greet };","lang":"javascript"}],"extra":["In this course the server code uses CommonJS so that the examples match the starter projects, and the React code uses import. When you read other people's code, expect to see both."],"id":"two-module-styles"},{"title":"What the plain server does for each request","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["The server in the next section checks req.url by hand.",false]],[["Here is what you would see if you ran these commands against it (assuming it answers / with text and /api/notices with JSON, and everything else with 404):",false]]]},{"k":"code","t":"curl -i http://localhost:3001/\n# HTTP/1.1 200 OK\n# Content-Type: text/plain\n# Hello from Node\n\ncurl -i http://localhost:3001/api/notices","lang":"bash"},{"k":"code","t":"# HTTP/1.1 200 OK\n# Content-Type: application/json\n# [{\"id\":1,\"title\":\"Library hours\"}]\n\ncurl -i http://localhost:3001/anything-else\n# HTTP/1.1 404 Not Found\n# Not found","lang":"javascript"},{"k":"callout","t":"Each branch is an if on the path, and each answer sets a status code and a Content-Type before sending the body. With three routes this is fine. With thirty routes the if chain becomes painful, and that is the problem Express solves next week."}],"id":"what-the-plain-server-does-for-each-request"},{"title":"A web server with no libraries","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Here is the smallest possible one.",false]],[["It shows what Express will make easier next week.",false]]]},{"k":"code","t":"const http = require(\"http\");\n\nconst server = http.createServer((req, res) => {\n  res.setHeader(\"Content-Type\", \"application/json\");\n  res.end(JSON.stringify({ message: \"Hello from Node\" }));\n});\n\nserver.listen(3001, () => console.log(\"http://localhost:3001\"));","lang":"javascript"}],"id":"a-web-server-with-no-libraries"},{"title":"Npm, the package manager","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["npm downloads other people's code (packages) and records what your project needs.",false]]]},{"k":"code","t":"npm init -y                 # create package.json\nnpm install express         # add a dependency\nnpm install --save-dev nodemon   # add a tool used only while developing","lang":"bash"},{"k":"table","head":["File or folder","What it is"],"rows":[["package.json","The project's description: name, scripts, and the packages it needs"],["package-lock.json","The exact versions installed, so everyone gets the same ones"],["node_modules/","The downloaded packages. It is large and can always be rebuilt"]]},{"k":"list","items":[[["Always add node_modules/ to a .gitignore file.",false]],[["Anyone who clones your project simply runs npm install to get it back.",false]]]}],"id":"npm-the-package-manager"},{"title":"One project, start to finish","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"mkdir notices-demo\ncd notices-demo\nnpm init -y                       # creates package.json\nnpm install express               # adds express to dependencies, creates node_modules\nnpm install --save-dev nodemon    # adds nodemon to devDependencies","lang":"bash"},{"k":"callout","t":"Your package.json now contains something like this:"},{"k":"code","t":"{\n  \"name\": \"notices-demo\",\n  \"version\": \"1.0.0\",\n  \"scripts\": {\n    \"start\": \"node server.js\",\n    \"dev\": \"nodemon server.js\"\n  },\n  \"dependencies\": { \"express\": \"^4.19.2\" },\n  \"devDependencies\": { \"nodemon\": \"^3.1.0\" }\n}","lang":"json"},{"k":"list","items":[[["Now imagine a classmate clones your project from GitHub.",false]]]},{"k":"list","items":[[["They get package.json but not node_modules, because you listed it in .gitignore.",false]],[["They run npm install, npm reads the two lists, downloads the same packages, and the project works on their computer.",false]]]}],"extra":["On a live server they would run npm start (which uses plain node) because nodemon is a developer convenience that production does not need."],"id":"one-project-start-to-finish"},{"title":"Scripts","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["The scripts section gives short names to long commands.",false]]]},{"k":"code","t":"\"scripts\": {\n  \"start\": \"node index.js\",\n  \"dev\": \"nodemon index.js\"\n}","lang":"javascript"},{"k":"callout","t":"Run them with npm start or npm run dev. nodemon restarts the server each time you save a file."}],"id":"scripts"}],"quiz":[{"q":"Which statement about node_modules is correct?","options":["It holds packages that can be rebuilt with npm install","It holds the source code that you wrote for this app","It must be committed so that others can run the app","It lists every script the project can run by its name"],"answer":0},{"q":"What is the difference between dependencies and devDependencies?","options":["The second group is for tools used only while developing","The second group is for packages that are optional to use","The first group is for tools used only while developing","The first group is for packages that the user must pay for"],"answer":0},{"q":"Why does document.querySelector fail when run with Node?","options":["Node has no web page, so there is no document object","Node cannot run any functions that were written by you","The querySelector method was removed from JavaScript","Node requires the page to be saved before it can run"],"answer":0},{"q":"What does npm run dev do in the example above?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Why do we ignore node_modules in Git?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Node.js. (n.d.-a). Learn. OpenJS Foundation. https://nodejs.org/en/learn","Node.js. (n.d.-b). Node.js documentation. OpenJS Foundation. https://nodejs.org/docs/latest/api/","npm. (n.d.-a). npm docs. https://docs.npmjs.com/","npm. (n.d.-b). package.json. https://docs.npmjs.com/cli/configuring-npm/package-json","nodemon. (n.d.). nodemon [Computer software]. npm. https://www.npmjs.com/package/nodemon","Preston-Werner, T. (n.d.). Semantic versioning 2.0.0. https://semver.org/"],"refsIntro":null,"slideCount":28,"pptx":"downloads/lecture/Week_04_Lecture_Node_js_and_npm.pptx"},{"week":5,"title":"Express: routing and middleware","focus":"building a server with Express","duration":"2 hours","file":"Week_05_Lecture_Express_routing_and_middleware.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can create an Express server, define routes that read parameters and queries, and write middleware that runs before your routes.",false]]]}],"id":"learning-outcomes"},{"title":"Why Express","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Last week's plain http server made you inspect req.url and req.method by hand for every request.",false]],[["Express is a small library that does that sorting for you, so you can write one clear function per route.",false]]]},{"k":"code","t":"npm init -y\nnpm install express","lang":"bash"},{"k":"code","t":"const express = require(\"express\");\nconst app = express();\nconst PORT = 3001;\n\napp.get(\"/\", (req, res) => {\n  res.send(\"Hello from Express\");\n});\n\napp.listen(PORT, () => console.log(`Running at http://localhost:${PORT}`));","lang":"javascript"}],"id":"why-express"},{"title":"Where does each part of the URL end up?","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"app.get(\"/api/notices/:id\", (req, res) => {\n  res.json({ params: req.params, query: req.query });\n});","lang":"javascript"},{"k":"table","head":["Request","What the handler sees"],"rows":[["GET /api/notices/3","params: { id: \"3\" }, query: {}"],["GET /api/notices/3?lang=fil","params: { id: \"3\" }, query: { lang: \"fil\" }"],["GET /api/notices/abc","params: { id: \"abc\" } (it still matches the route; your code must decide that abc is not a valid id)"],["GET /api/notices","No match for this route (there is no :id), so Express tries the next route or answers 404"]]},{"k":"list","items":[[["Two rules to remember.",false]],[["The path part (:id) names which thing you want, and the query part (?lang=fil) adjusts how you want it (filtering, searching, paging).",false]],[["And req.params.id is always a string:",false]]]}],"extra":["\"3\" is not equal to the number 3, which is why code like notices.find((n) => n.id === Number(req.params.id)) converts it first."],"id":"where-does-each-part-of-the-url-end-up"},{"title":"Routes","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["A route joins three things: an HTTP method, a path, and a function that handles it.",false]],[["The function receives req (what the client sent) and res (the tool for answering).",false]]]},{"k":"code","t":"const notices = [\n  { id: 1, title: \"Library hours extended\" },\n  { id: 2, title: \"Enrollment reminder\" },\n];\n\napp.get(\"/api/notices\", (req, res) => {","lang":"javascript"},{"k":"code","t":"  res.json(notices);\n});\n\n// route parameter: /api/notices/2\napp.get(\"/api/notices/:id\", (req, res) => {\n  const id = Number(req.params.id);\n  const notice = notices.find((n) => n.id === id);\n  if (!notice) {\n    return res.status(404).json({ error: \"Notice not found\" });\n  }\n  res.json(notice);\n});\n\n// query string: /api/search?term=library","lang":"javascript"},{"k":"code","t":"app.get(\"/api/search\", (req, res) => {\n  const term = (req.query.term || \"\").toLowerCase();\n  res.json(notices.filter((n) => n.title.toLowerCase().includes(term)));\n});","lang":"javascript"},{"k":"table","head":["Where the data is","How you read it","Example URL"],"rows":[["In the path","req.params.id","/api/notices/2"],["After the ?","req.query.term","/api/search?term=library"],["In the body","req.body.title","A POST with JSON (needs express.json())"]]}],"id":"routes"},{"title":"Ways to answer","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Each request must get exactly one answer.",false]]]},{"k":"table","head":["Method","Use it to"],"rows":[["res.send(text)","Send text or HTML"],["res.json(object)","Send JSON"],["res.status(404)","Set the status code, then chain .json(...)"],["res.redirect(url)","Send the client somewhere else"]]},{"k":"list","items":[[["A classic bug is answering twice.",false]],[["Writing return res.status(404).json(...) stops the function so the second answer never runs.",false]]]}],"id":"ways-to-answer"},{"title":"What the answer-once rule looks like in code","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"// Wrong: two answers for the same request\napp.get(\"/api/notices/:id\", (req, res) => {\n  const notice = notices.find((n) => n.id === Number(req.params.id));\n  if (!notice) {\n    res.status(404).json({ error: \"Not found\" });   // answer 1 ...\n  }\n  res.json(notice);                                  // ... and answer 2\n});","lang":"javascript"},{"k":"callout","t":"For an unknown id, the first answer is sent and then res.json(undefined) runs. The server prints Error [ERR_HTTP_HEADERS_SENT]: Cannot set headers after they are sent to the client. The fix is to stop the function after the first answer:"},{"k":"code","t":"if (!notice) {\n  return res.status(404).json({ error: \"Not found\" });  // return ends the function here\n}\nres.json(notice);","lang":"javascript"}],"id":"what-the-answer-once-rule-looks-like-in-code"},{"title":"Middleware","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Middleware is a function that runs between the request arriving and your route answering.",false]],[["It receives req, res and next.",false]],[["It can look at the request, change it, answer it, or call next() to pass it on.",false]]]},{"k":"code","t":"function logger(req, res, next) {\n  console.log(`${req.method} ${req.url}`);\n  next();\n}\n\napp.use(logger);            // runs for every request\napp.use(express.json());    // reads a JSON body into req.body\napp.use(express.static(\"public\")); // serves files from the public folder","lang":"javascript"}],"extra":["Think of the guard at a campus gate: he checks you, then waves you through."],"id":"middleware"},{"title":"Why order matters","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"const app = express();\n\napp.post(\"/api/notices\", (req, res) => {\n  console.log(req.body);      // runs BEFORE express.json() is registered\n  res.status(201).json({ ok: true });\n});\n\napp.use(express.json());      // too late for the route above","lang":"javascript"},{"k":"callout","t":"Send POST /api/notices with the JSON body { \"title\": \"Hello\" } and the console prints undefined. Express reached the route first, so nobody had turned the JSON text into an object yet. Move app.use(express.json()) above the route and the console prints { title: 'Hello' }."},{"k":"list","items":[[["A second example, with a logger:",false]]]},{"k":"code","t":"app.use((req, res, next) => {\n  console.log(`${req.method} ${req.url}`);\n  next();                    // pass the request along\n});","lang":"javascript"},{"k":"callout","t":"Visit /api/notices/2 and the terminal shows GET /api/notices/2 before the route answers. Delete the next() line and the page loads forever, because the request stops in the middleware and nobody ever answers it."}],"id":"why-order-matters"},{"title":"Order matters","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Express checks middleware and routes from top to bottom.",false]],[["That is why express.json() must come before the routes that need req.body, and why the catch-all 404 handler goes last.",false]]]},{"k":"code","t":"app.use((req, res) => {\n  res.status(404).json({ error: \"Route not found\" });\n});\n\n// error-handling middleware has FOUR parameters\napp.use((err, req, res, next) => {\n  console.error(err);","lang":"javascript"},{"k":"code","t":"  res.status(500).json({ error: \"Something went wrong\" });\n});","lang":"javascript"}],"id":"order-matters"}],"quiz":[{"q":"Where do you find the 3 in the request GET /api/notices/3?","options":["In req.params.id, because it is part of the path","In req.query.id, because it is part of the query","In req.body.id, because it is part of the body","In req.headers.id, because it is a header value"],"answer":0},{"q":"What happens if middleware forgets to call next() and does not answer?","options":["The request hangs, because nothing ever answers it","The next route runs anyway, so there is no problem","Express answers with a 200 status and empty body","Express restarts so that the server can recover"],"answer":0},{"q":"Why does the 404 handler go last?","options":["It should only run when no earlier route matched","It runs faster when it is placed at the bottom","Routes cannot be added after the first handler","It must be last so that the logger can run first"],"answer":0},{"q":"Write a route that responds to GET /api/ping with { \"pong\": true }.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"What does app.use(express.json()) do, and what breaks without it?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Express. (n.d.-a). Error handling. https://expressjs.com/en/guide/error-handling.html","Express. (n.d.-b). Routing. https://expressjs.com/en/guide/routing.html","Express. (n.d.-c). Serving static files in Express. https://expressjs.com/en/starter/static-files.html","Express. (n.d.-d). Using middleware. https://expressjs.com/en/guide/using-middleware.html","Postman. (n.d.). Postman Learning Center. https://learning.postman.com/docs/"],"refsIntro":null,"slideCount":27,"pptx":"downloads/lecture/Week_05_Lecture_Express_routing_and_middleware.pptx"},{"week":6,"title":"REST design, status codes and validation","focus":"designing an API other people can use","duration":"2 hours","file":"Week_06_Lecture_REST_design_status_codes_and_validation.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can design REST routes for a resource, choose the right status code, validate input on the server, and test an API with Postman.",false]]]}],"id":"learning-outcomes"},{"title":"What REST means in practice","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["REST is a set of habits for designing web APIs so they are predictable.",false]],[["The core ideas are:",false]],[["Resources are nouns. Name the thing, not the action: /api/notices, not /api/getAllNotices.",false]],[["Methods are the verbs. GET reads, POST creates, PUT replaces, PATCH changes part, DELETE removes.",false]]]},{"k":"list","items":[[["One URL, one resource. /api/notices is the collection, and /api/notices/3 is one item.",false]],[["The server remembers nothing between requests. Every request carries everything the server needs.",false]]]},{"k":"table","head":["Action","Method and URL","Success","Failure"],"rows":[["List all notices","GET /api/notices","200","none expected"],["Read one notice","GET /api/notices/:id","200","404 if it does not exist"],["Create a notice","POST /api/notices","201","400 if the data is invalid"],["Update a notice","PUT /api/notices/:id","200","400 invalid, 404 missing"],["Delete a notice","DELETE /api/notices/:id","204 (no body)","404 if it does not exist"]]}],"id":"what-rest-means-in-practice"},{"title":"Choosing the status code","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["For each situation in the Notices API, decide the answer before you look at the right-hand column.",false]]]},{"k":"table","head":["Situation","Status","Body"],"rows":[["GET /api/notices returns three notices","200","the array"],["POST /api/notices with a good title and message","201","the new notice, including its id"],["POST /api/notices with an empty title","400","{ \"error\": \"Title is required.\" }"],["GET /api/notices/99 and there is no notice 99","404","{ \"error\": \"Notice not found.\" }"],["PUT /api/notices/99 for a missing notice","404","{ \"error\": \"Notice not found.\" }"],["DELETE /api/notices/3 and it worked","204","none"],["The database is down","500","{ \"error\": \"Something went wrong.\" }"]]},{"k":"list","items":[[["A useful test: whose fault is it?",false]],[["If the client sent something wrong, the code is 4xx.",false]],[["If your server failed, it is 5xx.",false]]]}],"extra":["A missing title is the client's fault (400); a database crash is yours (500)."],"id":"choosing-the-status-code"},{"title":"Status codes are part of your API's meaning","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Do not return 200 for everything and hide the real result in the body.",false]],[["Clients, tools and teammates all rely on the code.",false]]]},{"k":"table","head":["Code","Say it when"],"rows":[["200 OK","A read or update worked"],["201 Created","A new resource was made"],["204 No Content","It worked and there is nothing to send back (a delete)"],["400 Bad Request","The client's data failed validation"],["404 Not Found","The route or item does not exist"],["500 Internal Server Error","The server itself failed"]]}],"id":"status-codes-are-part-of-your-api-s-meaning"},{"title":"What the validator does with different input","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Given this function:",false]]]},{"k":"code","t":"function validateNotice(body) {\n  const { title, message } = body || {};\n  if (typeof title !== \"string\" || title.trim() === \"\") return \"Title is required.\";\n  if (typeof message !== \"string\" || message.trim() === \"\") return \"Message is required.\";\n  if (title.trim().length > 100) return \"Title must be 100 characters or fewer.\";\n  return null;\n}","lang":"javascript"},{"k":"table","head":["Request body","Result","Reason"],"rows":[["{ \"title\": \"Hello\", \"message\": \"World\" }","null (valid)","Both fields are real text"],["{ \"title\": \"   \", \"message\": \"World\" }","\"Title is required.\"","Spaces only, so trim() leaves nothing"],["{ \"title\": 42, \"message\": \"World\" }","\"Title is required.\"","A number is not a string"],["{ \"title\": \"Hello\" }","\"Message is required.\"","message is undefined"],["no body at all","\"Title is required.\"","The fallback to an empty object in the first line stops a crash"],["a 120-character title","\"Title must be 100 characters or fewer.\"","Too long"]]},{"k":"list","items":[[["Notice the order: the cheapest, most basic checks come first, and each failure returns immediately with one clear message.",false]]]}],"id":"what-the-validator-does-with-different-input"},{"title":"Validate on the server, always","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["A form in the browser can be bypassed with Postman or a script.",false]],[["The server is the last line of defence, so it must check every input.",false]],[["Return 400 with a message the client can show.",false]]]},{"k":"code","t":"function validateNotice(body) {\n  const { title, message } = body || {};\n  if (typeof title !== \"string\" || title.trim() === \"\") {\n    return \"Title is required.\";\n  }","lang":"javascript"},{"k":"code","t":"  if (typeof message !== \"string\" || message.trim() === \"\") {\n    return \"Message is required.\";\n  }\n  if (title.trim().length > 100) {\n    return \"Title must be 100 characters or fewer.\";\n  }\n  return null; // null means valid\n}","lang":"javascript"},{"k":"callout","t":"Keep the error shape the same everywhere, for example { \"error\": \"Title is required.\" }. Clients can then handle every failure in one place."}],"id":"validate-on-the-server-always"},{"title":"A complete in-memory CRUD API","tag":"CONCEPT","kind":"concept","blocks":[{"k":"code","t":"const express = require(\"express\");\nconst cors = require(\"cors\");\n\nconst app = express();\napp.use(cors());\napp.use(express.json());\n\nlet notices = [\n  { id: 1, title: \"Library hours extended\", message: \"Open until 9 PM.\", createdAt: \"2026-10-12T08:00:00.000Z\" },\n];\nlet nextId = 2;\n\napp.get(\"/api/notices\", (req, res) => res.json(notices));","lang":"javascript"},{"k":"code","t":"\napp.get(\"/api/notices/:id\", (req, res) => {\n  const notice = notices.find((n) => n.id === Number(req.params.id));\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(notice);\n});\n\napp.post(\"/api/notices\", (req, res) => {\n  const problem = validateNotice(req.body);\n  if (problem) return res.status(400).json({ error: problem });\n\n  const notice = {\n    id: nextId++,","lang":"javascript"},{"k":"code","t":"    title: req.body.title.trim(),\n    message: req.body.message.trim(),\n    createdAt: new Date().toISOString(),\n  };\n  notices.push(notice);\n  res.status(201).json(notice);\n});\n\napp.put(\"/api/notices/:id\", (req, res) => {\n  const notice = notices.find((n) => n.id === Number(req.params.id));\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n\n  const problem = validateNotice(req.body);","lang":"javascript"},{"k":"code","t":"  if (problem) return res.status(400).json({ error: problem });\n\n  notice.title = req.body.title.trim();\n  notice.message = req.body.message.trim();\n  res.json(notice);\n});\n\napp.delete(\"/api/notices/:id\", (req, res) => {\n  const index = notices.findIndex((n) => n.id === Number(req.params.id));\n  if (index === -1) return res.status(404).json({ error: \"Notice not found.\" });\n  notices.splice(index, 1);\n  res.status(204).send();\n});","lang":"javascript"},{"k":"code","t":"\napp.listen(3001, () => console.log(\"API on http://localhost:3001\"));","lang":"javascript"},{"k":"callout","t":"The data lives in an array, so it disappears when the server restarts. Next week fixes that."}],"id":"a-complete-in-memory-crud-api"},{"title":"One complete request/response pair","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["A client creates a notice.",false]],[["In Postman you would set the method to POST, the URL to http://localhost:3001/api/notices, choose Body, raw, JSON, and send:",false]]]},{"k":"code","t":"{ \"title\": \"Enrollment reminder\", \"message\": \"Last day to add or drop is Friday.\" }","lang":"json"},{"k":"callout","t":"The server answers:"},{"k":"code","t":"Status: 201 Created\nContent-Type: application/json\n\n{\n  \"id\": 4,\n  \"title\": \"Enrollment reminder\",\n  \"message\": \"Last day to add or drop is Friday.\",\n  \"createdAt\": \"2026-10-16T07:30:00.000Z\"\n}","lang":"javascript"},{"k":"callout","t":"Now break it on purpose: send { \"title\": \"\" } and you should see 400 Bad Request with { \"error\": \"Title is required.\" }. Send GET /api/notices/4 and you should get the new notice back with 200. That small cycle (create, read it back, break it) is the pattern for every Postman test you write."}],"id":"one-complete-request-response-pair"},{"title":"Postman","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Postman sends requests without a browser, so you can test the API before any interface exists.",false]],[["Learn three features: saving requests in a collection, setting the JSON body under Body > raw > JSON, and writing small automatic checks in the Tests tab.",false]]]},{"k":"code","t":"pm.test(\"Status is 201\", () => {\n  pm.response.to.have.status(201);\n});\n\npm.test(\"Response has an id\", () => {\n  const body = pm.response.json();\n  pm.expect(body).to.have.property(\"id\");\n});","lang":"javascript"}],"id":"postman"}],"quiz":[{"q":"Which URL follows REST naming habits?","options":["GET /api/notices/3 to read the notice with an id of three","GET /api/getNotice?id=3 to read the notice with id three","POST /api/readNotice/3 to read the notice with id of three","GET /api/notices/read/3 to read the notice with id of three"],"answer":0},{"q":"What should DELETE /api/notices/3 return when it succeeds?","options":["204 with no body, because there is nothing to send back","201 with the deleted item, because the task was created","400 with an error text, because the item was removed now","302 with a new address, because the item is gone for now"],"answer":0},{"q":"Why validate on the server when the form already checks the input?","options":["Anyone can send requests that skip the form completely","Servers are faster at checking text than the browser is","Browsers are not able to check that a field is not empty","The form checks only run when the user has a slow link"],"answer":0},{"q":"A client sends PUT /api/notices/99 and no notice 99 exists. Which status code do you return?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Why is it better to keep the same error shape everywhere?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Google Cloud. (n.d.). API design guide. https://cloud.google.com/apis/design","MDN Contributors. (n.d.-a). HTTP request methods. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/Methods","MDN Contributors. (n.d.-b). HTTP response status codes. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/Status","Microsoft. (n.d.). Microsoft REST API guidelines. GitHub. https://github.com/microsoft/api-guidelines","OWASP Foundation. (n.d.). Input validation cheat sheet. OWASP Cheat Sheet Series. https://cheatsheetseries.owasp.org/cheatsheets/Input_Validation_Cheat_Sheet.html","Postman. (n.d.). Write scripts to test API response data. Postman Learning Center. https://learning.postman.com/docs/tests-and-scripts/write-scripts/test-scripts/"],"refsIntro":null,"slideCount":29,"pptx":"downloads/lecture/Week_06_Lecture_REST_design_status_codes_and_validation.pptx"},{"week":7,"title":"MongoDB and Mongoose basics","focus":"giving your API a memory","duration":"2 hours","file":"Week_07_Lecture_MongoDB_and_Mongoose_basics.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can explain what a database is for, describe MongoDB's collections and documents, and use Mongoose to define a schema, connect to a database, and save and read data.",false]]]}],"id":"learning-outcomes"},{"title":"Why a database","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Your Week 6 API forgot every notice when the server restarted, because the data lived in an array in memory.",false]],[["A database stores data on disk, so it survives restarts, can be shared by many servers, and can be searched quickly.",false]]]}],"id":"why-a-database"},{"title":"The same notice in your array and in the database","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["In Week 6 a notice lived in a JavaScript array.",false]],[["In MongoDB it is a document inside a collection called notices.",false]]]},{"k":"table","head":["In your Week 6 code","In MongoDB"],"rows":[["The array notices","The collection notices"],["One object in the array","One document"],["{ id: 1, title: \"Library hours\" }","{ _id: ObjectId(\"652f1c...\"), title: \"Library hours\", createdAt: ... }"],["nextId++ to make an id","MongoDB makes _id for you"],["Lost when the server restarts","Kept on disk"]]},{"k":"list","items":[[["Two documents in the same collection do not have to look identical.",false]],[["This is allowed in MongoDB, and it is the reason we add rules with a Mongoose schema (the next sections) so that every notice has the fields we expect.",false]]]}],"id":"the-same-notice-in-your-array-and-in-the-databas"},{"title":"MongoDB's way of storing data","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["MongoDB is a document database.",false]],[["Instead of rows in tables, it stores JSON-like documents in collections.",false]]]},{"k":"table","head":["Idea","In a spreadsheet or SQL","In MongoDB"],"rows":[["One record","Row","Document"],["A group of records","Table","Collection"],["The whole store","Database","Database"],["Unique identifier","Primary key","_id (an ObjectId, added automatically)"]]},{"k":"code","t":"{\n  \"_id\": \"6710a3b2c4d5e6f708192a3b\",\n  \"title\": \"Library hours extended\",\n  \"message\": \"Open until 9 PM during midterm week.\",\n  \"createdAt\": \"2026-10-12T08:00:00.000Z\"\n}","lang":"json"},{"k":"callout","t":"Notice _id with an underscore. Until now we used id. Any React page that reads MongoDB data must use _id."}],"id":"mongodb-s-way-of-storing-data"},{"title":"Getting a database","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["You have two choices.",false]],[["Use whichever works on your network.",false]],[["MongoDB Atlas (free tier). Create an account, create a free cluster, add a database user, allow your IP address under Network Access, then copy the connection string.",false]],[["A local MongoDB install. Start the server and use mongodb://127.0.0.1:27017/campus-notices.",false]],[["Keep the connection string out of your code.",false]],[["Put it in a .env file and add .env to .gitignore.",false]]]},{"k":"code","t":"npm install mongoose dotenv","lang":"bash"},{"k":"code","t":"# .env\nMONGODB_URI=mongodb://127.0.0.1:27017/campus-notices","lang":"javascript"}],"id":"getting-a-database"},{"title":"Reading a connection string","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"mongodb+srv://notices_user:S3cretPass@cluster0.ab1cd.mongodb.net/campus-notices?retryWrites=true","lang":"text"},{"k":"table","head":["Part","What it is"],"rows":[["mongodb+srv://","The protocol: talk to MongoDB (the +srv form is used by Atlas)"],["notices_user","The database user you created"],["S3cretPass","That user's password, which is why this string must never go into your code or GitHub"],["cluster0.ab1cd.mongodb.net","The server (the host)"],["/campus-notices","The name of your database"],["?retryWrites=true","An option"]]},{"k":"list","items":[[["If your password contains a character such as @ or #, it must be percent-encoded in the string (@ becomes %40), or the connection fails with an authentication error.",false]],[["The local equivalent is the much shorter mongodb://127.0.0.1:27017/campus-notices, with no user or password.",false]]]}],"id":"reading-a-connection-string"},{"title":"Mongoose","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Mongoose sits between your code and MongoDB.",false]],[["It lets you describe the shape of your data once, then gives you ready-made methods.",false]]]},{"k":"code","t":"// db.js\nrequire(\"dotenv\").config();\nconst mongoose = require(\"mongoose\");\n\nasync function connectDB() {\n  try {\n    await mongoose.connect(process.env.MONGODB_URI);","lang":"javascript"},{"k":"code","t":"    console.log(\"MongoDB connected\");\n  } catch (err) {\n    console.error(\"MongoDB connection failed:\", err.message);\n    process.exit(1);\n  }\n}\n\nmodule.exports = connectDB;","lang":"javascript"},{"k":"callout","t":"A schema describes the fields and rules. A model is the tool built from the schema that talks to the collection."},{"k":"code","t":"// models/Notice.js\nconst mongoose = require(\"mongoose\");\n\nconst noticeSchema = new mongoose.Schema(\n  {\n    title: { type: String, required: true, trim: true, maxlength: 100 },\n    message: { type: String, required: true, trim: true, maxlength: 500 },\n  },\n  { timestamps: true } // adds createdAt and updatedAt automatically\n);\n\nmodule.exports = mongoose.model(\"Notice\", noticeSchema);","lang":"javascript"}],"id":"mongoose"},{"title":"Schema validation in action","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"const noticeSchema = new mongoose.Schema({\n  title:   { type: String, required: true, trim: true, maxlength: 100 },\n  message: { type: String, required: true, trim: true },\n});\nconst Notice = mongoose.model(\"Notice\", noticeSchema);","lang":"javascript"},{"k":"callout","t":"See what the model does with each attempt:"},{"k":"code","t":"await Notice.create({ title: \"  Library hours  \", message: \"Open until 9 PM\" });\n// saved, and the title is stored as \"Library hours\" because of trim: true\n\nawait Notice.create({ message: \"No title here\" });\n// throws ValidationError: Notice validation failed: title: Path `title` is required.\n\nawait Notice.create({ title: \"x\".repeat(150), message: \"Too long\" });\n// throws ValidationError: ... is longer than the maximum allowed length (100).","lang":"javascript"},{"k":"callout","t":"The schema is your first line of defence. Nothing invalid reaches the collection, and in Week 8 you will turn these ValidationErrors into friendly 400 answers."}],"id":"schema-validation-in-action"},{"title":"Reading and writing","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Almost every Mongoose method returns a promise, so you use await.",false]]]},{"k":"table","head":["Task","Code"],"rows":[["Create one","await Notice.create({ title, message })"],["Read all","await Notice.find()"],["Read all, newest first","await Notice.find().sort({ createdAt: -1 })"],["Read one by id","await Notice.findById(id)"]]},{"k":"code","t":"// seed.js : fill the database with sample data\nconst connectDB = require(\"./db\");\nconst Notice = require(\"./models/Notice\");\n\nasync function seed() {\n  await connectDB();\n  await Notice.deleteMany({});\n  await Notice.create([\n    { title: \"Library hours extended\", message: \"Open until 9 PM during midterm week.\" },\n    { title: \"Enrollment reminder\", message: \"Last day to add or drop subjects is Friday.\" },\n  ]);\n  console.log(\"Seeded\");","lang":"javascript"},{"k":"code","t":"  process.exit(0);\n}\n\nseed();","lang":"javascript"}],"id":"reading-and-writing"}],"quiz":[{"q":"What is a MongoDB collection most like?","options":["A table, holding many related documents of one kind","A column, holding values for one single field only","A server, holding many databases for a company now","A file, holding the code for one single route handler"],"answer":0},{"q":"Why keep the connection string in a .env file?","options":["It holds a password and must stay out of the repository","It makes the database respond a lot faster than before","Mongoose will only connect when the string is in a file","It is the only way that the string can include a number"],"answer":0},{"q":"What does { timestamps: true } do in a Mongoose schema?","options":["It adds createdAt and updatedAt fields on its own","It makes the database slow down to check each field","It stops anyone from changing a document after it is saved","It sorts all documents with the oldest document first"],"answer":0},{"q":"Why must we write await Notice.find() and not just Notice.find()?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"What is the difference between a schema and a model?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["dotenv. (n.d.). dotenv [Computer software]. npm. https://www.npmjs.com/package/dotenv","MongoDB. (n.d.-a). MongoDB Atlas documentation. https://www.mongodb.com/docs/atlas/","MongoDB. (n.d.-b). MongoDB manual. https://www.mongodb.com/docs/manual/","Mongoose. (n.d.-a). Getting started. https://mongoosejs.com/docs/index.html","Mongoose. (n.d.-b). Schemas. https://mongoosejs.com/docs/guide.html","Mongoose. (n.d.-c). Validation. https://mongoosejs.com/docs/validation.html","Wiggins, A. (2017). III. Config. In The twelve-factor app. https://12factor.net/config"],"refsIntro":null,"slideCount":27,"pptx":"downloads/lecture/Week_07_Lecture_MongoDB_and_Mongoose_basics.pptx"},{"week":8,"title":"Mongoose CRUD, error handling and review","focus":"a complete, persistent API","duration":"2 hours","file":"Week_08_Lecture_Mongoose_CRUD_error_handling_and_review.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can write all four CRUD operations with Mongoose, handle errors in one central place, and organise a server into routes, controllers, models and middleware.",false]],[["The second half of the session reviews Weeks 1 to 8 before the midterm.",false]]]}],"id":"learning-outcomes"},{"title":"The four operations in Mongoose","tag":"CONCEPT","kind":"concept","blocks":[{"k":"table","head":["Operation","Mongoose call","Notes"],"rows":[["Create","Notice.create(data)","Runs the schema validation first"],["Read","Notice.find() and Notice.findById(id)","findById gives null when nothing matches"],["Update","Notice.findByIdAndUpdate(id, data, { new: true, runValidators: true })","new: true returns the updated document, and runValidators applies schema rules"],["Delete","Notice.findByIdAndDelete(id)","Gives null when nothing matches"]]}],"id":"the-four-operations-in-mongoose"},{"title":"The four operations and what they return","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"// Create\nconst n = await Notice.create({ title: \"Contest\", message: \"Sign up by Monday\" });\n// n = { _id: \"652f...\", title: \"Contest\", message: \"...\", createdAt: ..., updatedAt: ... }\n\n// Read\nawait Notice.find();                 // an array of every notice (an empty array if none)\nawait Notice.findById(n._id);        // one notice, or null if it does not exist\n\n// Update","lang":"javascript"},{"k":"code","t":"await Notice.findByIdAndUpdate(n._id, { title: \"Contest moved\" }, { new: true, runValidators: true });\n// the UPDATED notice (without new: true you would get the OLD one back)\n\n// Delete\nawait Notice.findByIdAndDelete(n._id);  // the deleted notice, or null if it was not there","lang":"javascript"},{"k":"list","items":[[["Notice the pattern for \"not found\": findById, findByIdAndUpdate and findByIdAndDelete return null for an unknown id.",false]],[["Your controller checks for null and answers 404.",false]]]}],"extra":["The two options matter too: true returns the fresh document, and runValidators: true makes updates obey the schema, because updates skip validation by default."],"id":"the-four-operations-and-what-they-return"},{"title":"Async routes and errors","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["In Express 4, an error thrown inside an async function is not caught automatically.",false]],[["The request would hang.",false]],[["A tiny wrapper sends the error to Express's error handler through next.",false]]]},{"k":"code","t":"// middleware/asyncHandler.js\nmodule.exports = (fn) => (req, res, next) =>\n  Promise.resolve(fn(req, res, next)).catch(next);","lang":"javascript"}],"id":"async-routes-and-errors"},{"title":"Why an async error hangs the request","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"// Express 4, no protection\napp.get(\"/api/notices/:id\", async (req, res) => {\n  const notice = await Notice.findById(req.params.id);  // throws CastError for id \"abc\"\n  res.json(notice);\n});","lang":"javascript"},{"k":"callout","t":"Request GET /api/notices/abc. The await throws, but Express 4 does not catch errors from async functions, so no answer is ever sent. In Postman the request spins until it times out, and the server may print UnhandledPromiseRejection. The one-line wrapper fixes it:"},{"k":"code","t":"const asyncHandler = (fn) => (req, res, next) =>\n  Promise.resolve(fn(req, res, next)).catch(next);   // send any error to the error handler\n\napp.get(\"/api/notices/:id\", asyncHandler(async (req, res) => {\n  const notice = await Notice.findById(req.params.id);\n  res.json(notice);\n}));","lang":"javascript"},{"k":"callout","t":"Now the same request reaches your central error handler, which answers 400 { \"error\": \"Invalid id.\" } immediately."}],"id":"why-an-async-error-hangs-the-request"},{"title":"Controllers keep routes small","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["A route file only maps URLs to functions.",false]],[["The controller holds the logic.",false]]]},{"k":"code","t":"// controllers/noticeController.js\nconst Notice = require(\"../models/Notice\");\nconst asyncHandler = require(\"../middleware/asyncHandler\");\n\nexports.getNotices = asyncHandler(async (req, res) => {\n  const notices = await Notice.find().sort({ createdAt: -1 });\n  res.json(notices);\n});","lang":"javascript"},{"k":"code","t":"exports.createNotice = asyncHandler(async (req, res) => {\n  const { title, message } = req.body;\n  const notice = await Notice.create({ title, message });\n  res.status(201).json(notice);\n});\n\nexports.updateNotice = asyncHandler(async (req, res) => {\n  const { title, message } = req.body;\n  const notice = await Notice.findByIdAndUpdate(\n    req.params.id,\n    { title, message },\n    { new: true, runValidators: true }\n  );","lang":"javascript"},{"k":"code","t":"  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.json(notice);\n});\n\nexports.deleteNotice = asyncHandler(async (req, res) => {\n  const notice = await Notice.findByIdAndDelete(req.params.id);\n  if (!notice) return res.status(404).json({ error: \"Notice not found.\" });\n  res.status(204).send();\n});","lang":"javascript"},{"k":"code","t":"// routes/notices.js\nconst express = require(\"express\");\nconst c = require(\"../controllers/noticeController\");\n\nconst router = express.Router();\nrouter.get(\"/\", c.getNotices);\nrouter.post(\"/\", c.createNotice);\nrouter.put(\"/:id\", c.updateNotice);\nrouter.delete(\"/:id\", c.deleteNotice);\n\nmodule.exports = router;","lang":"javascript"},{"k":"callout","t":"In app.js, mount it with app.use(\"/api/notices\", noticeRoutes)."}],"id":"controllers-keep-routes-small"},{"title":"One request through every layer","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["A client sends POST /api/notices with { \"title\":",false]],[["\"Contest\", \"message\":",false]],[["\"Sign up\" }.",false]]]},{"k":"table","head":["Step","File","What happens"],"rows":[["1","app.js","express.json() turns the body into req.body"],["2","app.js","app.use(\"/api/notices\", noticeRoutes) sends the request to the router"],["3","routes/notices.js","router.post(\"/\", createNotice) picks the controller"]]},{"k":"table","head":["Step","File","What happens"],"rows":[["4","controllers/noticeController.js","Notice.create({ title, message }) is called inside asyncHandler"],["5","models/Notice.js","The schema checks the rules and MongoDB saves the document"],["6","the controller","res.status(201).json(notice) sends the answer"]]},{"k":"list","items":[[["Now imagine the title is empty.",false]],[["Step 5 throws a ValidationError, asyncHandler passes it to next(err), Express skips the remaining routes, and the error handler answers 400.",false]]]},{"k":"list","items":[[["Each file has one job, which is why a bug is easy to locate: wrong status code?",false]]]}],"extra":["Look in the controller. Wrong field rule? Look in the model."],"id":"one-request-through-every-layer"},{"title":"One place for errors","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Instead of repeating try/catch in every route, let errors travel to a single handler registered last.",false]]]},{"k":"code","t":"// middleware/errorHandler.js\nmodule.exports = (err, req, res, next) => {\n  if (err.name === \"ValidationError\") {\n    const message = Object.values(err.errors).map((e) => e.message).join(\" \");\n    return res.status(400).json({ error: message });\n  }\n  if (err.name === \"CastError\") {\n    return res.status(400).json({ error: \"Invalid id.\" });","lang":"javascript"},{"k":"code","t":"  }\n  console.error(err); // the real error stays on the server\n  res.status(500).json({ error: \"Something went wrong.\" });\n};","lang":"javascript"},{"k":"callout","t":"Never send raw error details to the client. They can reveal how your server works."}],"id":"one-place-for-errors"},{"title":"Recommended folder layout","tag":"CONCEPT","kind":"concept","blocks":[{"k":"code","t":"server/\n  app.js              the Express app\n  server.js           connects to the database, then listens\n  db.js\n  models/Notice.js\n  controllers/noticeController.js\n  routes/notices.js\n  middleware/asyncHandler.js\n  middleware/errorHandler.js","lang":"javascript"}],"id":"recommended-folder-layout"},{"title":"Review: what you should be able to do after Week 8","tag":null,"kind":"divider","sub":"For the review half of the session, put students in pairs.","id":"review-what-you-should-be-able-to-do-after-week-"}],"quiz":[{"q":"Why do we wrap async route handlers in asyncHandler?","options":["Express 4 does not catch errors thrown inside async code","It makes the database queries run faster than before now","Express cannot run any function that has the async label","It converts every callback into a promise for the client"],"answer":0},{"q":"What does findByIdAndUpdate return by default, when new: true is not set?","options":["The document as it was before the update was applied","The document as it looks after the update was applied","The number of documents that were changed by the update","An empty value, since an update never returns anything"],"answer":0},{"q":"A client sends GET /api/notices/abc. Which error does Mongoose raise?","options":["A CastError, because abc is not a valid ObjectId value","A ValidationError, because abc is not a valid title text","A SyntaxError, because abc is not a valid JSON document","A TypeError, because abc is not a number that we can use"],"answer":0},{"q":"Why must the error handler have four parameters?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Why is the real error logged on the server but not sent to the client?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Express. (n.d.-a). Error handling. https://expressjs.com/en/guide/error-handling.html","Express. (n.d.-b). Routing. https://expressjs.com/en/guide/routing.html","Mongoose. (n.d.-a). Models. https://mongoosejs.com/docs/models.html","Mongoose. (n.d.-b). Queries. https://mongoosejs.com/docs/queries.html","Mongoose. (n.d.-c). Validation: Update validators. https://mongoosejs.com/docs/validation.html#update-validators"],"refsIntro":"Martin, R. C. (2017). Clean architecture: A craftsman's guide to software structure and design. Prentice Hall.","slideCount":26,"pptx":"downloads/lecture/Week_08_Lecture_Mongoose_CRUD_error_handling_and_review.pptx"},{"week":9,"title":"Midterm","focus":"the written midterm","duration":"2 hours","file":"Week_09_Lecture_Midterm.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["The midterm covers Weeks 1 to 8.",false]],[["It checks that you understand why things work, not only that you can type them.",false]],[["The written part takes the 2-hour lecture slot.",false]]]},{"k":"table","head":["Topic","Weeks","Share of the written exam"],"rows":[["HTTP, requests, responses, status codes","1, 6","15%"],["Modern JavaScript and the DOM","2","15%"],["Asynchronous JavaScript, fetch, JSON","3","20%"],["Node and npm","4","10%"]]},{"k":"table","head":["Topic","Weeks","Share of the written exam"],"rows":[["Express routing and middleware","5","20%"],["MongoDB, Mongoose and error handling","7, 8","20%"]]},{"k":"list","items":[[["The written exam has multiple-choice items, short answers, and one \"read this code and explain it\" question.",false]],[["You may bring one handwritten page of notes.",false]]]}],"extra":["The practical part takes the lab."],"id":"learning-outcomes"},{"title":"How to prepare","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Redo one lab from memory without looking at your old code.",false]],[["Explain each week's key idea aloud to a classmate in one minute.",false]],[["Re-read the \"Check your understanding\" questions from each chapter and answer them without notes.",false]],[["Break your own API on purpose, and write down every error message and what caused it.",false]]]}],"id":"how-to-prepare"}],"quiz":[{"q":"Which statement about fetch is true?","options":["It resolves on a 404, so you must check res.ok yourself","It rejects on a 404, so the catch block always handles it","It returns the parsed object, so no more parsing is needed","It blocks all other code until the whole response arrives"],"answer":0},{"q":"In Express, which line must come before routes that read req.body?","options":["app.use(express.json()) to parse the incoming JSON text","app.listen(3001) to start up the server at the right port","app.use(notFound) to answer any route that does not exist","app.get(\"/\") to answer requests for the home page first"],"answer":0},{"q":"What is the purpose of package-lock.json?","options":["It records exact installed versions so installs match","It stops other people from reading the project source","It lists the scripts that can be run with the npm tool","It holds secrets such as the database connection string"],"answer":0},{"q":"Which status code fits \"the data you sent failed validation\"?","options":["400, because the problem is in the request the client sent","404, because the problem is that the page was not located","500, because the problem is a bug inside the server itself","204, because the problem is that there is no content to see"],"answer":0},{"q":"What does this code print, and why? const a = [1,2,3]; console.log(a.map(n => n * 2), a);","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"A POST request reaches your route but req.body is undefined. Give two possible causes.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Explain the difference between dependencies and devDependencies, with one example of each.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Describe, step by step, what happens when a browser loads http://localhost:3001/api/notices.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Express. (n.d.-a). Routing. https://expressjs.com/en/guide/routing.html","Express. (n.d.-b). Using middleware. https://expressjs.com/en/guide/using-middleware.html","MDN Contributors. (n.d.-a). HTTP response status codes. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/Status","MDN Contributors. (n.d.-b). Using the Fetch API. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch","Mongoose. (n.d.-a). Queries. https://mongoosejs.com/docs/queries.html","Mongoose. (n.d.-b). Validation. https://mongoosejs.com/docs/validation.html","Postman. (n.d.). Postman Learning Center. https://learning.postman.com/docs/"],"refsIntro":"The midterm covers Weeks 1 to 8, so use the references from those chapters. The most useful ones to reread are:","slideCount":14,"pptx":"downloads/lecture/Week_09_Lecture_Midterm.pptx"},{"week":10,"title":"PostgreSQL and SQL fundamentals","focus":"from documents to tables, and the SQL to query them","duration":"2 hours","file":null,"sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can explain tables, rows, primary keys and foreign keys, install PostgreSQL and connect with psql or pgAdmin, create tables with data types and constraints, and write SELECT, INSERT, UPDATE, DELETE, join and aggregate queries.",false]]]}],"id":"learning-outcomes"},{"title":"From documents to tables","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Weeks 7 and 8 used MongoDB, where a notice is a document in a collection. From this week we use PostgreSQL, a relational database.",false]],[["In a relational database, data lives in tables. A table has columns (each with a type) and rows (one per notice).",false]],[["A primary key is a column whose value identifies exactly one row. A foreign key is a column that points at the primary key of another table, and that is how tables are related.",false]]]},{"k":"table","head":["MongoDB (Weeks 7 to 8)","PostgreSQL"],"rows":[["Collection notices","Table notices"],["Document","Row"],["Field","Column, with a fixed type"],["_id (ObjectId)","id, the primary key"],["Embedding or referencing","A foreign key such as notices.category_id"],["Schema enforced by Mongoose","Schema enforced by the database itself"]]},{"k":"callout","t":"The big difference: PostgreSQL checks your rules itself. Even code that skips your validation cannot store a row that breaks a constraint."}],"id":"from-documents-to-tables"},{"title":"Installing PostgreSQL, psql and pgAdmin","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Install PostgreSQL 14 or newer. The installer includes the server, psql (a terminal client) and pgAdmin (a visual client).",false]],[["Choose a password for the postgres user and remember it. The server listens on port 5432 by default.",false]]]},{"k":"code","t":"psql --version\npsql -U postgres","lang":"bash"},{"k":"callout","t":"A prompt ending in =# means you are connected. If psql is not found, the PostgreSQL bin folder is not on your PATH (on Windows it is usually C:\\Program Files\\PostgreSQL\\<version>\\bin). Add it, or open SQL Shell (psql) from the Start menu."},{"k":"table","head":["psql command","What it does"],"rows":[["\\l","List databases"],["\\c notices_db","Connect to a database"],["\\dt","List tables"],["\\d notices","Show a table's columns and constraints"],["\\q","Quit"]]}],"id":"installing-postgresql-psql-and-pgadmin"},{"title":"Creating the categories and notices tables","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Create the parent table first, because notices will point at it.",false]],[["Notice how each column has a type, and how the rules are written next to the column.",false]]]},{"k":"code","t":"CREATE DATABASE notices_db;\n\\c notices_db\n\nCREATE TABLE categories (\n  id SERIAL PRIMARY KEY,\n  name VARCHAR(30) NOT NULL UNIQUE\n);\n\nCREATE TABLE notices (\n  id SERIAL PRIMARY KEY,\n  title VARCHAR(120) NOT NULL,\n  message TEXT NOT NULL,\n  category_id INTEGER REFERENCES categories(id),\n  pinned BOOLEAN NOT NULL DEFAULT false,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  CHECK (length(trim(title)) > 0)\n);","lang":"sql"},{"k":"callout","t":"REFERENCES categories(id) is the foreign key. PostgreSQL now refuses a notice whose category_id does not exist in categories."}],"id":"creating-the-categories-and-notices-tables"},{"title":"Data types and constraints","tag":"CONCEPT","kind":"concept","blocks":[{"k":"table","head":["Type","Use it for"],"rows":[["SERIAL / INTEGER","Ids and whole numbers (SERIAL counts up by itself)"],["VARCHAR(n) / TEXT","Short text with a limit / text of any length"],["BOOLEAN","true or false, such as pinned"],["TIMESTAMPTZ","A date and time with time zone, such as created_at"]]},{"k":"table","head":["Constraint","What it guarantees"],"rows":[["PRIMARY KEY","Unique, never empty; identifies the row"],["NOT NULL","The column must have a value"],["UNIQUE","No two rows share the value"],["DEFAULT","The value used when you do not supply one"],["CHECK","A rule the value must satisfy"],["REFERENCES","The value must exist in another table (foreign key)"]]}],"id":"data-types-and-constraints"},{"title":"Reading data: SELECT, WHERE and ORDER BY","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["SELECT chooses columns, FROM chooses the table, WHERE keeps matching rows, ORDER BY sorts.",false]],[["Text in SQL uses single quotes. ILIKE is a case-insensitive search.",false]]]},{"k":"code","t":"SELECT * FROM notices;\n\nSELECT id, title FROM notices\nWHERE pinned = true\nORDER BY created_at DESC;\n\nSELECT title FROM notices\nWHERE title ILIKE '%library%'\nLIMIT 5;","lang":"sql"}],"id":"reading-data-select-where-and-order-by"},{"title":"Changing data: INSERT, UPDATE and DELETE","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["INSERT adds a row, UPDATE changes rows, DELETE removes rows.",false]],[["Always put a WHERE on UPDATE and DELETE. Without it, every row changes.",false]]]},{"k":"code","t":"INSERT INTO categories (name) VALUES ('academic'), ('events'), ('urgent');\n\nINSERT INTO notices (title, message, category_id)\nVALUES ('Library hours extended', 'Open until 9 PM.', 1)\nRETURNING *;\n\nUPDATE notices SET pinned = true WHERE id = 1;\n\nDELETE FROM notices WHERE id = 1;","lang":"sql"},{"k":"callout","t":"RETURNING * hands back the row that was just written. You will use it in Week 11 to answer a POST request."}],"id":"changing-data-insert-update-and-delete"},{"title":"Joins: notices with their category names","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["A notice stores only category_id. To show the category name, join the two tables on the key.",false]]]},{"k":"code","t":"SELECT n.title, c.name AS category\nFROM notices n\nJOIN categories c ON c.id = n.category_id;\n\nSELECT n.title, c.name AS category\nFROM notices n\nLEFT JOIN categories c ON c.id = n.category_id;","lang":"sql"},{"k":"table","head":["Join","Rows returned"],"rows":[["JOIN (inner)","Only notices that have a matching category"],["LEFT JOIN","Every notice; category is empty (NULL) when there is no match"]]}],"id":"joins-notices-with-their-category-names"},{"title":"Aggregates and GROUP BY","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Aggregate functions summarise many rows into one value: COUNT, MIN, MAX, AVG, SUM.",false]],[["GROUP BY makes one summary row per group.",false]]]},{"k":"code","t":"SELECT COUNT(*) FROM notices;\n\nSELECT c.name, COUNT(n.id) AS total\nFROM categories c\nLEFT JOIN notices n ON n.category_id = c.id\nGROUP BY c.name\nORDER BY total DESC;","lang":"sql"}],"id":"aggregates-and-group-by"},{"title":"Think, pair, share: document versus relational","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["With a partner, decide where each model fits best for the Campus Notices Board.",false]],[["Be ready to explain one advantage of each.",false]]]},{"k":"table","head":["Question","Document (MongoDB)","Relational (PostgreSQL)"],"rows":[["Data with a fixed, clear shape","Works, but nothing enforces the shape unless you add it","Natural fit; the database enforces it"],["Linking notices to categories","Embed or store an id and look it up yourself","Foreign key and a join"],["Changing the shape later","Easy: just add a field","Needs ALTER TABLE or a migration"],["Summaries and reports","Aggregation pipeline","GROUP BY and aggregates"]]}],"id":"think-pair-share-document-versus-relational"}],"quiz":[{"q":"What does a primary key guarantee?","options":["Each row has a unique, non-empty value that identifies it","The rows are stored in alphabetical order","The column can never be updated","The table can never be joined with another table"],"answer":0},{"q":"You run UPDATE notices SET pinned = true; with no WHERE clause. What happens?","options":["Every row in the table is updated","Only the first row is updated","PostgreSQL refuses with a syntax error","Only rows that were not already pinned are updated"],"answer":0},{"q":"What does notices.category_id REFERENCES categories(id) prevent?","options":["A notice pointing at a category that does not exist","Two notices having the same title","A notice having an empty message","A category having a name"],"answer":0},{"q":"Which query keeps notices that have no category (category_id is NULL)?","options":["notices LEFT JOIN categories","notices JOIN categories (inner join)","Neither; rows with NULL are always dropped","SELECT DISTINCT only"],"answer":0},{"q":"Compare how one notice is stored in MongoDB and in PostgreSQL. Name one advantage of each.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["PostgreSQL Global Development Group. (n.d.-a). CREATE TABLE. In PostgreSQL documentation. https://www.postgresql.org/docs/current/sql-createtable.html","PostgreSQL Global Development Group. (n.d.-b). Tutorial. In PostgreSQL documentation. https://www.postgresql.org/docs/current/tutorial.html","PostgreSQL Global Development Group. (n.d.-c). Aggregate functions. In PostgreSQL documentation. https://www.postgresql.org/docs/current/tutorial-agg.html","PostgreSQL Global Development Group. (n.d.-d). Joins between tables. In PostgreSQL documentation. https://www.postgresql.org/docs/current/tutorial-join.html","pgAdmin Development Team. (n.d.). pgAdmin documentation. https://www.pgadmin.org/docs/"],"refsIntro":null,"slideCount":null,"pptx":null},{"week":11,"title":"Express with PostgreSQL (pg)","focus":"your API on a relational database","duration":"2 hours","file":null,"sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can connect an Express app to PostgreSQL with the pg library and a connection pool, write parameterized queries that prevent SQL injection, return rows as JSON with the right status codes, and migrate the notices API from Mongoose to raw SQL.",false]]]}],"id":"learning-outcomes"},{"title":"From Mongoose to pg","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Your routes and Postman collection stay the same. Only the data layer changes.",false]],[["Mongoose gave you models and methods. With pg you write the SQL yourself and the database does the checking.",false]]]},{"k":"table","head":["Mongoose (Week 8)","pg with raw SQL"],"rows":[["mongoose.connect(...)","new Pool({ connectionString })"],["Notice.find()","SELECT * FROM notices"],["Notice.findById(id)","SELECT ... WHERE id = $1"],["Notice.create(body)","INSERT ... VALUES ($1, $2) RETURNING *"],["Notice.findByIdAndUpdate(...)","UPDATE ... WHERE id = $1 RETURNING *"],["Notice.findByIdAndDelete(id)","DELETE ... WHERE id = $1"],["ValidationError, CastError","PostgreSQL error codes such as 23502 and 22P02"]]}],"id":"from-mongoose-to-pg"},{"title":"Installing pg and connecting","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Install the node-postgres library, called pg, and keep the connection string in a .env file.",false]],[["Create one file, db.js, that every controller imports.",false]]]},{"k":"code","t":"npm install pg dotenv","lang":"bash"},{"k":"code","t":"// db.js\nrequire(\"dotenv\").config();\nconst { Pool } = require(\"pg\");\n\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL });\n\nmodule.exports = { query: (text, params) => pool.query(text, params) };","lang":"javascript"},{"k":"code","t":"# .env\nDATABASE_URL=postgres://postgres:YOUR_PASSWORD@localhost:5432/notices_db","lang":"text"},{"k":"callout","t":"Never commit .env. Add it to .gitignore before your first commit."}],"id":"installing-pg-and-connecting"},{"title":"Connection pool versus single client","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["A Client is one connection. Opening one per request is slow and can exhaust the database.",false]],[["A Pool keeps a small set of open connections and lends them out. pool.query borrows one, runs the query and returns it.",false]],[["Use pool.query for almost everything. Borrow a single client (pool.connect) only when several statements must share one connection, such as a transaction.",false]]]}],"id":"connection-pool-versus-single-client"},{"title":"Parameterized queries","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Write the SQL with placeholders $1, $2 and pass the values as a separate array.",false]],[["The database receives the SQL and the values separately, so the values can never be read as SQL.",false]]]},{"k":"code","t":"const { rows } = await db.query(\n  \"INSERT INTO notices (title, message, category_id) VALUES ($1, $2, $3) RETURNING *\",\n  [title, message, categoryId]\n);\nres.status(201).json(rows[0]);","lang":"javascript"},{"k":"callout","t":"Never build SQL by joining strings with user input. That is how SQL injection happens, and you will see it break a table in this week's lab."}],"id":"parameterized-queries"},{"title":"Rows become JSON","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["A query returns a result object. The part you need is result.rows, an array of plain objects.",false]]]},{"k":"code","t":"const result = await db.query(\"SELECT id, title FROM notices WHERE id = $1\", [2]);\nconsole.log(result.rows);      // [ { id: 2, title: 'Foundation Day program' } ]\nconsole.log(result.rowCount);  // 1","lang":"javascript"},{"k":"table","head":["Situation","rows","Reply"],"rows":[["List notices","Array of rows (maybe empty)","200 with the array"],["Get one notice, found","[ row ]","200 with rows[0]"],["Get one notice, not found","[]","404"],["Create a notice","[ new row ] from RETURNING *","201 with rows[0]"],["Delete, nothing deleted","rowCount is 0","404"]]}],"id":"rows-become-json"},{"title":"One route, Mongoose versus pg","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"// Week 8: Mongoose\nconst notice = await Notice.findById(req.params.id);\nif (!notice) return res.status(404).json({ error: \"Notice not found.\" });\nres.json(notice);","lang":"javascript"},{"k":"code","t":"// Week 11: pg\nconst { rows } = await db.query(\"SELECT * FROM notices WHERE id = $1\", [req.params.id]);\nif (rows.length === 0) return res.status(404).json({ error: \"Notice not found.\" });\nres.json(rows[0]);","lang":"javascript"},{"k":"callout","t":"The shape of the controller is the same. The 404 check moves from a null result to an empty rows array."}],"id":"one-route-mongoose-versus-pg"},{"title":"Handling database errors","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["PostgreSQL reports errors with a short code. Keep the central error handler you wrote in Week 8, and teach it these codes.",false]]]},{"k":"table","head":["Code","Meaning","Reply"],"rows":[["22P02","Bad value for the type, such as the id abc","400"],["23502","A NOT NULL column was left empty","400"],["23503","A foreign key points at a row that does not exist","400"],["23505","A UNIQUE rule failed","409"]]},{"k":"code","t":"function errorHandler(err, req, res, next) {\n  if (err.code === \"22P02\") return res.status(400).json({ error: \"Invalid id.\" });\n  if (err.code === \"23502\" || err.code === \"23503\") return res.status(400).json({ error: \"Invalid data.\" });\n  if (err.code === \"23505\") return res.status(409).json({ error: \"Already exists.\" });\n  console.error(err);\n  res.status(500).json({ error: \"Something went wrong.\" });\n}","lang":"javascript"}],"id":"handling-database-errors"},{"title":"Migrating the notices API","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Create the tables in notices_db (Week 10) and add a few rows to test with.",false]],[["Install pg and dotenv, and add db.js.",false]],[["Replace one controller function at a time, and test it before you move on.",false]],[["Run your Week 6 Postman collection; it should pass with only small changes.",false]],[["When every route passes, remove mongoose from the project.",false]]]}],"id":"migrating-the-notices-api"}],"quiz":[{"q":"Why pass values as a separate array ($1, $2) instead of building the SQL string yourself?","options":["The database treats the values as data, so input cannot change the SQL","It always makes the query run faster","It makes the query return JSON instead of rows","Express requires it"],"answer":0},{"q":"What does result.rows contain after a SELECT?","options":["An array of row objects, empty if nothing matched","Only the number of rows found","A single object even when many rows match","A Mongoose document"],"answer":0},{"q":"A SELECT by id returns rows equal to []. Which response is correct?","options":["404 Not Found","200 with an empty object","500 Internal Server Error","201 Created"],"answer":0},{"q":"Why use a Pool instead of creating a new Client for every request?","options":["A pool reuses a limited set of open connections, which is cheaper under load","A pool encrypts every query","A client cannot run SELECT","A pool makes the database faster than its hardware allows"],"answer":0},{"q":"GET /api/notices/abc makes PostgreSQL throw error code 22P02. What should the error handler reply?","options":["400 with an invalid-id message","404 Not Found","500 Internal Server Error","409 Conflict"],"answer":0}],"refs":["node-postgres. (n.d.-a). Pooling. https://node-postgres.com/features/pooling","node-postgres. (n.d.-b). Queries. https://node-postgres.com/features/queries","OWASP Foundation. (n.d.-a). Query parameterization cheat sheet. OWASP Cheat Sheet Series. https://cheatsheetseries.owasp.org/cheatsheets/Query_Parameterization_Cheat_Sheet.html","OWASP Foundation. (n.d.-b). SQL injection. https://owasp.org/www-community/attacks/SQL_Injection","PostgreSQL Global Development Group. (n.d.). Appendix A. PostgreSQL error codes. In PostgreSQL documentation. https://www.postgresql.org/docs/current/errcodes-appendix.html"],"refsIntro":null,"slideCount":null,"pptx":null},{"week":12,"title":"React: components and props","focus":"building the interface from small pieces","duration":"2 hours","file":"Week_12_Lecture_React_components_and_props.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can create a React project, write components in JSX, pass data into them with props, and render lists correctly.",false]]]}],"id":"learning-outcomes"},{"title":"The idea","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["A web page is made of repeating parts: a notice card, a button, a header.",false]],[["React lets you write each part once as a component, a JavaScript function that returns what that part should look like.",false]],[["You then assemble components like building blocks.",false]]]}],"id":"the-idea"},{"title":"Starting a project","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["We use Vite, a fast tool that sets up everything React needs.",false]]]},{"k":"code","t":"npm create vite@latest notices-ui -- --template react\ncd notices-ui\nnpm install\nnpm run dev","lang":"bash"},{"k":"callout","t":"Open the address it prints. The code you will edit is in src/App.jsx."}],"id":"starting-a-project"},{"title":"JSX","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["JSX looks like HTML inside JavaScript.",false]],[["It is converted to plain JavaScript before the browser sees it.",false]],[["It has a few rules that differ from HTML:",false]]]},{"k":"table","head":["In HTML you write","In JSX you write","Why"],"rows":[["class=\"card\"","className=\"card\"","class is a reserved word in JavaScript"],["<br> and <img ...>","<br /> and <img ... />","Every tag must be closed"],["Two siblings at the top","Wrap them in one parent or in <>...</>","A component returns one root"],["Text with a value","{value} in curly braces","Curly braces run JavaScript"]]},{"k":"code","t":"function Greeting() {\n  const name = \"Maria\";\n  return <h2>Welcome, {name}!</h2>;\n}","lang":"javascript"}],"id":"jsx"},{"title":"HTML becoming JSX","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Copy a card from your Week 1 page and convert it.",false]],[["Three small changes are needed.",false]]]},{"k":"code","t":"<!-- HTML -->\n<article class=\"notice\">\n  <h2>Library hours</h2>\n  <img src=\"lib.png\">\n  <label for=\"q\">Search</label>\n</article>","lang":"xml"},{"k":"code","t":"// JSX\nconst card = (\n  <article className=\"notice\">\n    <h2>{title}</h2>\n    <img src=\"lib.png\" />\n    <label htmlFor=\"q\">Search</label>\n  </article>\n);","lang":"javascript"},{"k":"table","head":["Change","Why"],"rows":[["class becomes className","class is already a reserved word in JavaScript"],["for becomes htmlFor","for is also reserved"],["<img> becomes <img />","Every tag must be closed in JSX"],["Library hours becomes {title}","Curly braces run JavaScript, so the text can come from a variable"]]},{"k":"list","items":[[["Also remember that a component must return one parent element.",false]],[["Two sibling tags need a wrapper such as <div> or an empty fragment <>...</>, or you get Adjacent JSX elements must be wrapped in an enclosing tag.",false]]]}],"id":"html-becoming-jsx"},{"title":"Components and props","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["A component's name starts with a capital letter.",false]],[["Props are the inputs you give it, written like HTML attributes.",false]],[["Props flow in one direction, from parent to child, and a component must never change its own props.",false]]]},{"k":"code","t":"// NoticeCard.jsx\nexport default function NoticeCard({ title, message, pinned }) {\n  return (\n    <article className=\"card\">\n      <h3>{title}</h3>","lang":"javascript"},{"k":"code","t":"      <p>{message}</p>\n      {pinned && <span className=\"badge\">Pinned</span>}\n    </article>\n  );\n}","lang":"xml"},{"k":"code","t":"// App.jsx\nimport NoticeCard from \"./NoticeCard\";\n\nexport default function App() {\n  return (\n    <main>\n      <h1>Campus Notices</h1>","lang":"javascript"},{"k":"code","t":"      <NoticeCard\n        title=\"Library hours extended\"\n        message=\"Open until 9 PM during midterm week.\"\n        pinned\n      />\n    </main>\n  );\n}","lang":"javascript"},{"k":"callout","t":"The expression {pinned && <span ...>} is conditional rendering: the badge appears only when pinned is true."}],"id":"components-and-props"},{"title":"One component, three different cards","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"function NoticeCard({ title, pinned }) {\n  return (\n    <article>\n      <h2>{pinned && \"📌 \"}{title}</h2>\n    </article>\n  );\n}\n\n// Using it three times with different props\n<NoticeCard title=\"Library hours\" pinned={true} />\n<NoticeCard title=\"Enrollment\" pinned={false} />\n<NoticeCard title=\"Programming cup\" />","lang":"javascript"},{"k":"callout","t":"The three cards render as:"},{"k":"code","t":"📌 Library hours\nEnrollment\nProgramming cup","lang":"text"},{"k":"list","items":[[["The third card has no pinned prop at all, so inside the component pinned is undefined, and undefined && \"...\" shows nothing.",false]],[["The { title, pinned } in the function's brackets is just destructuring (Week 2) applied to the props object.",false]]]}],"extra":["Props go down, from parent to child, and the child must never change them."],"id":"one-component-three-different-cards"},{"title":"Rendering lists","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Use map, which you learned in Week 2, to turn an array of data into an array of components.",false]],[["Each item needs a key, a value that is unique among its siblings.",false]],[["React uses keys to track which item is which when the list changes.",false]]]},{"k":"code","t":"const notices = [\n  { id: 1, title: \"Library hours extended\", message: \"Open until 9 PM.\", pinned: true },\n  { id: 2, title: \"Enrollment reminder\", message: \"Add or drop ends Friday.\", pinned: false },\n];\n\nfunction NoticeList({ notices }) {\n  if (notices.length === 0) {\n    return <p>No notices yet.</p>;\n  }\n  return (\n    <section>\n      {notices.map((n) => (","lang":"javascript"},{"k":"code","t":"        <NoticeCard key={n.id} title={n.title} message={n.message} pinned={n.pinned} />\n      ))}\n    </section>\n  );\n}","lang":"javascript"},{"k":"callout","t":"Use a stable id for the key. Avoid the array index unless the list never changes order."}],"id":"rendering-lists"},{"title":"A list with and without keys","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"const notices = [\n  { id: 11, title: \"Library hours\" },\n  { id: 12, title: \"Enrollment\" },\n  { id: 13, title: \"Programming cup\" },\n];\n\nfunction NoticeList({ notices }) {\n  return (\n    <ul>\n      {notices.map((n) => (\n        <li key={n.id}>{n.title}</li>\n      ))}\n    </ul>\n  );","lang":"javascript"},{"k":"code","t":"}","lang":"text"},{"k":"list","items":[[["If you remove key={n.id}, the page still draws, but the Console warns Each child in a list should have a unique \"key\" prop.",false]],[["Why it matters: suppose the first item is deleted.",false]]]}],"extra":["With keys, React sees \"the item with key 11 is gone\" and removes just that one row. With the index as the key, it thinks item 0 changed text and item 2 disappeared, which causes wrong animations and, later in forms, text stuck in the wrong row. Use the database id, because it follows the item wherever it moves."],"id":"a-list-with-and-without-keys"},{"title":"Thinking in components","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Look at a design and draw boxes around the repeated and logical parts.",false]],[["Each box is a candidate component.",false]],[["Aim for small components that do one job.",false]]]}],"id":"thinking-in-components"}],"quiz":[{"q":"Why do we write className in JSX instead of class?","options":["The word class is already reserved in JavaScript code","The word class is not allowed in the browsers we use","The word className loads the CSS file a lot more quickly","The word class can only be used on heading elements"],"answer":0},{"q":"What is the purpose of the key prop in a list?","options":["It helps React tell the items apart when a list changes","It makes the items appear in the same order as the array","It is used to style each of the items with a unique color","It stops the user from clicking on more than one of them"],"answer":0},{"q":"A child component tries to change a value it received as a prop. What is the right approach?","options":["Props are read-only, so the parent should own the value","Props can be changed freely as long as the name is the same","The child should copy the prop into a global variable first","React will update the parent when the child changes a prop"],"answer":0},{"q":"Write a component Badge that shows the text from a prop called label.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Why is the index a risky choice for a key when the list can be reordered?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Meta Open Source. (n.d.-a). Conditional rendering. React. https://react.dev/learn/conditional-rendering","Meta Open Source. (n.d.-b). Learn React. React. https://react.dev/learn","Meta Open Source. (n.d.-c). Rendering lists. React. https://react.dev/learn/rendering-lists","Meta Open Source. (n.d.-d). Thinking in React. React. https://react.dev/learn/thinking-in-react","Vite. (n.d.). Getting started. https://vite.dev/guide/"],"refsIntro":null,"slideCount":27,"pptx":"downloads/lecture/Week_12_Lecture_React_components_and_props.pptx"},{"week":13,"title":"React: state, events and forms","focus":"making the interface respond","duration":"2 hours","file":"Week_13_Lecture_React_state_events_and_controlled_forms.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can store changing data with useState, respond to events, build a controlled form, and update lists without changing the original data.",false]]]}],"id":"learning-outcomes"},{"title":"A plain variable versus state","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Here are two counters.",false]],[["Only one works.",false]]]},{"k":"code","t":"// Broken: the number changes but the screen does not\nfunction BrokenCounter() {\n  let count = 0;\n  return <button onClick={() => { count = count + 1; console.log(count); }}>Clicked {count}</button>;\n}","lang":"javascript"},{"k":"code","t":"// Works: React is told about the change\nimport { useState } from \"react\";\n\nfunction Counter() {\n  const [count, setCount] = useState(0);\n  return <button onClick={() => setCount(count + 1)}>Clicked {count}</button>;\n}","lang":"javascript"},{"k":"list","items":[[["In BrokenCounter the console prints 1, 2, 3 but the button always says \"Clicked 0\", because React was never asked to redraw.",false]]]}],"extra":["In Counter, calling setCount stores the new value and asks React to run the component again, so the button shows the new number. useState(0) returns a pair: the current value and the function to change it. This is the same idea you saw in Week 2 (\"change the data, then draw again\"), now done for you."],"id":"a-plain-variable-versus-state"},{"title":"State is memory for a component","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Props come from outside.",false]],[["State belongs to the component, and when it changes, React draws the component again.",false]],[["A normal variable would change but the screen would not, because React does not know it changed.",false]]]},{"k":"code","t":"import { useState } from \"react\";\n\nfunction LikeButton() {\n  const [likes, setLikes] = useState(0); // [current value, function to change it]\n\n  return (\n    <button onClick={() => setLikes(likes + 1)}>\n      Likes: {likes}\n    </button>\n  );\n}","lang":"javascript"},{"k":"callout","t":"useState(0) gives you two things: the current value and a setter. Always change state with the setter, never by assigning to the variable."}],"id":"state-is-memory-for-a-component"},{"title":"Events","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["React events are written in camelCase and receive a function: onClick, onChange, onSubmit.",false]],[["Pass the function itself.",false]],[["Writing onClick={handle()} would call it immediately while rendering.",false]]]}],"id":"events"},{"title":"Controlled inputs","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["In a controlled input, React state is the single source of truth.",false]],[["The input shows the state's value, and every keystroke updates the state.",false]]]},{"k":"code","t":"function NoticeForm({ onAdd }) {\n  const [title, setTitle] = useState(\"\");\n  const [message, setMessage] = useState(\"\");\n  const [error, setError] = useState(\"\");\n\n  function handleSubmit(event) {\n    event.preventDefault(); // stop the browser from reloading the page","lang":"javascript"},{"k":"code","t":"\n    if (title.trim() === \"\" || message.trim() === \"\") {\n      setError(\"Please fill in both fields.\");\n      return;\n    }\n    onAdd({ title: title.trim(), message: message.trim() });\n    setTitle(\"\");\n    setMessage(\"\");\n    setError(\"\");\n  }\n\n  return (\n    <form onSubmit={handleSubmit}>\n      <label htmlFor=\"title\">Title</label>","lang":"xml"},{"k":"code","t":"      <input id=\"title\" value={title} onChange={(e) => setTitle(e.target.value)} />\n\n      <label htmlFor=\"message\">Message</label>\n      <textarea id=\"message\" value={message} onChange={(e) => setMessage(e.target.value)} />\n\n      {error && <p role=\"alert\">{error}</p>}\n      <button type=\"submit\">Post notice</button>\n    </form>\n  );\n}","lang":"xml"}],"id":"controlled-inputs"},{"title":"Follow a controlled input keystroke by keystroke","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"function TitleBox() {\n  const [title, setTitle] = useState(\"\");\n  return (\n    <>\n      <input value={title} onChange={(e) => setTitle(e.target.value)} />\n      <p>You typed: {title}</p>\n    </>\n  );\n}","lang":"javascript"},{"k":"callout","t":"Type the word Hi:"},{"k":"table","head":["Keystroke","What React does"],"rows":[["(start)","title is \"\", the box is empty, the paragraph says \"You typed: \""],["H","onChange fires with e.target.value = \"H\", setTitle(\"H\") runs, the component redraws"],["i","onChange fires with \"Hi\", setTitle(\"Hi\"), redraw"]]},{"k":"list","items":[[["The box always shows whatever title holds, so state is the single source of truth.",false]],[["A useful experiment: remove the onChange line and try to type.",false]],[["Nothing appears, because the box is forced to show the unchanging title, and the Console warns that you gave value without onChange.",false]]]}],"id":"follow-a-controlled-input-keystroke-by-keystroke"},{"title":"Never change state directly","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["React compares old and new state to decide whether to redraw.",false]],[["If you change an array in place, the reference stays the same and React may not notice.",false]],[["Build a new array or object, using the spread syntax from Week 2.",false]]]},{"k":"table","head":["You want to...","Write this"],"rows":[["Add an item","setNotices([...notices, newNotice])"],["Remove an item","setNotices(notices.filter((n) => n.id !== id))"],["Change one item","setNotices(notices.map((n) => n.id === id ? { ...n, pinned: true } : n))"]]}],"id":"never-change-state-directly"},{"title":"The wrong way and the right way to add to a list","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"const [notices, setNotices] = useState([{ id: 1, title: \"Library hours\" }]);\n\n// Wrong: changes the same array, so React sees no difference and does not redraw\nfunction addWrong() {\n  notices.push({ id: 2, title: \"New one\" });\n  setNotices(notices);\n}\n\n// Right: a brand new array\nfunction addRight() {\n  setNotices([{ id: 2, title: \"New one\" }, ...notices]);\n}","lang":"javascript"},{"k":"callout","t":"The same rule gives you the other two list operations:"},{"k":"code","t":"// delete: filter builds a new array without the item\nsetNotices(notices.filter((n) => n.id !== 2));\n\n// update one item: map builds a new array, and spread copies the changed item\nsetNotices(notices.map((n) => (n.id === 1 ? { ...n, pinned: true } : n)));","lang":"javascript"},{"k":"callout","t":"Remember Week 2: map, filter and spread never modify the original. That is exactly why they are React's tools for changing state."}],"id":"the-wrong-way-and-the-right-way-to-add-to-a-list"},{"title":"Lifting state up","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["When two components need the same data, move the state to their closest common parent and pass it down as props.",false]],[["Here App owns the list, and passes onAdd to the form and notices to the list.",false]]]},{"k":"code","t":"export default function App() {\n  const [notices, setNotices] = useState([]);\n\n  function addNotice(data) {\n    const notice = { id: Date.now(), createdAt: new Date().toISOString(), ...data };","lang":"javascript"},{"k":"code","t":"    setNotices([...notices, notice]);\n  }\n\n  return (\n    <main>\n      <NoticeForm onAdd={addNotice} />\n      <NoticeList notices={notices} />\n    </main>\n  );\n}","lang":"xml"},{"k":"callout","t":"Date.now() is only a temporary id. In Week 15 the server will give us the real one."}],"id":"lifting-state-up"},{"title":"Which component owns the state?","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Your page has a form that adds notices and a list that shows them.",false]]]},{"k":"code","t":"App                  <- holds the notices array (state lives here)\n ├─ NoticeForm        <- needs a way to ADD (receives onAdd)\n └─ NoticeList        <- needs the array to SHOW (receives notices)","lang":"javascript"},{"k":"code","t":"function App() {\n  const [notices, setNotices] = useState([]);\n  return (\n    <>\n      <NoticeForm onAdd={(n) => setNotices([n, ...notices])} />\n      <NoticeList notices={notices} />","lang":"javascript"},{"k":"code","t":"    </>\n  );\n}","lang":"javascript"},{"k":"callout","t":"If the array lived inside NoticeForm, the list could never see it. If it lived inside NoticeList, the form could never change it. So the state moves up to the nearest parent that contains both. Data flows down as props, and events flow up as function props such as onAdd."}],"id":"which-component-owns-the-state"},{"title":"Derived data","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Do not store something you can calculate.",false]],[["If you have a search text in state, compute the filtered list while rendering.",false]]]},{"k":"code","t":"const visible = notices.filter((n) =>\n  n.title.toLowerCase().includes(search.toLowerCase())\n);","lang":"javascript"}],"id":"derived-data"},{"title":"Derived data for the search box","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"const [notices, setNotices] = useState(initialNotices);\nconst [search, setSearch] = useState(\"\");\n\n// Derived: calculated on every render, never stored\nconst visible = notices.filter((n) =>\n  n.title.toLowerCase().includes(search.toLowerCase())\n);","lang":"javascript"},{"k":"list","items":[[["Suppose notices holds \"Library hours\", \"Enrollment\" and \"Library fine\".",false]]]},{"k":"list","items":[[["Typing lib sets search to \"lib\", the component runs again, and visible becomes the two library notices.",false]],[["If you now delete \"Library fine\", notices changes, the component runs again, and visible automatically drops to one item.",false]]]}],"extra":["If you had stored the filtered list in its own state, you would have to remember to update it in every place that changes notices, and sooner or later it would show stale data. One source of truth, everything else calculated."],"id":"derived-data-for-the-search-box"}],"quiz":[{"q":"Why does a plain variable not update the screen when it changes?","options":["React redraws only when state is changed using a setter","React cannot read any variables that are declared in a file","Plain variables are deleted by the browser after each use","The screen only updates when the page itself is reloaded"],"answer":0},{"q":"Which line correctly adds a notice to state?","options":["setNotices([...notices, newNotice]) so a new array is made","notices.push(newNotice) so the original array has the item","notices = [...notices, newNotice] so the variable holds it","setNotices(notices.push(newNotice)) to save the new length"],"answer":0},{"q":"What does event.preventDefault() do in handleSubmit?","options":["It stops the browser from reloading the page on submit","It stops the user from typing any more into the inputs","It checks that the form has no errors before it is sent","It sends the form data to the server without a request"],"answer":0},{"q":"In a controlled input, what two props connect it to state?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Two sibling components need the same list. Where should the state live, and why?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Meta Open Source. (n.d.-a). Choosing the state structure. React. https://react.dev/learn/choosing-the-state-structure","Meta Open Source. (n.d.-b). Reacting to input with state. React. https://react.dev/learn/reacting-to-input-with-state","Meta Open Source. (n.d.-c). Responding to events. React. https://react.dev/learn/responding-to-events","Meta Open Source. (n.d.-d). Sharing state between components. React. https://react.dev/learn/sharing-state-between-components","Meta Open Source. (n.d.-e). State: A component's memory. React. https://react.dev/learn/state-a-components-memory","Meta Open Source. (n.d.-f). Updating arrays in state. React. https://react.dev/learn/updating-arrays-in-state","PostgreSQL Global Development Group. (n.d.-a). Constraints. In PostgreSQL documentation. https://www.postgresql.org/docs/current/ddl-constraints.html","PostgreSQL Global Development Group. (n.d.-b). Queries. In PostgreSQL documentation. https://www.postgresql.org/docs/current/queries.html"],"refsIntro":null,"slideCount":31,"pptx":"downloads/lecture/Week_13_Lecture_React_state_events_and_controlled_forms.pptx"},{"week":14,"title":"React: effects and data fetching","focus":"loading data into a component","duration":"2 hours","file":"Week_14_Lecture_React_effects_fetching_loading_and_error.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can run code when a component appears, fetch data from your API inside useEffect, and show loading, error and empty states.",false]]]}],"id":"learning-outcomes"},{"title":"Side effects","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Rendering should only calculate what to show.",false]],[["Anything else, such as fetching data, setting a timer or changing the page title, is a side effect, and React gives it its own home: useEffect.",false]]]},{"k":"code","t":"import { useEffect, useState } from \"react\";\n\nuseEffect(() => {\n  document.title = \"Campus Notices\";\n}, []); // the dependency array","lang":"javascript"}],"id":"side-effects"},{"title":"When does the effect run?","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"function Demo({ search }) {\n  console.log(\"render\");\n\n  useEffect(() => {\n    console.log(\"effect A (no array)\");\n  });\n\n  useEffect(() => {\n    console.log(\"effect B ([])\");\n  }, []);\n\n  useEffect(() => {\n    console.log(\"effect C ([search])\", search);\n  }, [search]);","lang":"javascript"},{"k":"code","t":"\n  return <p>{search}</p>;\n}","lang":"xml"},{"k":"callout","t":"Suppose the page loads with search = \"\", then the user types l and then li. The console shows:"},{"k":"table","head":["Moment","Console"],"rows":[["First draw","render, then effect A, effect B, effect C"],["After typing l","render, then effect A, effect C ([search]) l (B does not run)"],["After typing li","render, then effect A, effect C ([search]) li"]]},{"k":"list","items":[[["Effect A runs after every render, which is how infinite loops start when it also sets state.",false]],[["Effect B runs once, which is what you want for \"load the notices when the page opens\".",false]]]}],"extra":["Effect C runs when search changes, which is what you want for \"load again when the search text changes\"."],"id":"when-does-the-effect-run"},{"title":"The dependency array decides when the effect runs","tag":"CONCEPT","kind":"concept","blocks":[{"k":"table","head":["Dependency array","When the effect runs"],"rows":[["[]","Once, after the first render"],["[search]","After the first render, and again whenever search changes"],["none at all","After every render (rarely what you want, and a common cause of infinite loops)"]]}],"id":"the-dependency-array-decides-when-the-effect-run"},{"title":"Fetching in an effect","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["The function you give to useEffect cannot itself be async, because it must return either nothing or a cleanup function.",false]],[["Declare an async function inside it and call it.",false]]]}],"id":"fetching-in-an-effect"},{"title":"The infinite loop, and the one-character fix","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"// Broken: sets state inside an effect with no dependency array\nuseEffect(() => {\n  fetch(\"/api/notices\")\n    .then((res) => res.json())\n    .then((data) => setNotices(data));   // changes state, which re-renders, which runs the effect again\n});","lang":"javascript"},{"k":"callout","t":"Symptoms: the server terminal prints GET /api/notices over and over, dozens of times a second, and the browser feels slow. The chain is: render, effect fetches, setNotices changes state, React renders again, the effect runs again, and so on forever. The fix is the dependency array:"},{"k":"code","t":"useEffect(() => {\n  fetch(\"/api/notices\").then((res) => res.json()).then(setNotices);\n}, []);   // run once, after the first render","lang":"javascript"},{"k":"callout","t":"Now the terminal shows a single request per page load. (In development, React 18's Strict Mode deliberately runs effects twice to help you find bugs, so seeing two requests in development is normal.)"}],"id":"the-infinite-loop-and-the-one-character-fix"},{"title":"Three states for every fetch","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Real networks are slow and fail.",false]],[["A fetching component should always handle three situations: loading, error and success (and for a list, the empty case).",false]]]},{"k":"code","t":"function NoticeBoard() {\n  const [notices, setNotices] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(\"\");\n\n  useEffect(() => {\n    let ignore = false; // protects against stale responses","lang":"javascript"},{"k":"code","t":"\n    async function load() {\n      try {\n        setLoading(true);\n        setError(\"\");\n        const res = await fetch(\"http://localhost:3001/api/notices\");\n        if (!res.ok) throw new Error(`Server answered ${res.status}`);\n        const data = await res.json();\n        if (!ignore) setNotices(data);\n      } catch (err) {\n        if (!ignore) setError(\"Could not load notices. Is the server running?\");\n      } finally {\n        if (!ignore) setLoading(false);","lang":"javascript"},{"k":"code","t":"      }\n    }\n\n    load();\n    return () => {\n      ignore = true; // cleanup: runs if the component goes away\n    };\n  }, []);\n\n  if (loading) return <p>Loading notices...</p>;\n  if (error) return <p role=\"alert\">{error}</p>;\n  if (notices.length === 0) return <p>No notices yet.</p>;\n\n  return (","lang":"xml"},{"k":"code","t":"    <section>\n      {notices.map((n) => (\n        <article key={n.id}>\n          <h3>{n.title}</h3>\n          <p>{n.message}</p>\n        </article>\n      ))}\n    </section>\n  );\n}","lang":"xml"},{"k":"callout","t":"Three details to notice:"},{"k":"list","items":[[["The early return lines handle each state in turn, so the main markup stays simple.",false]],[["The ignore flag stops a slow, old response from overwriting newer data. In development, React runs effects twice on purpose to expose this kind of bug.",false]],[["The key uses n.id, because the primary key of the notices table is id. If your API uses an in-memory id, use that instead.",false]]]}],"id":"three-states-for-every-fetch"},{"title":"Following the three states over time","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["The user opens the page, and the API takes two seconds to answer.",false]]]},{"k":"table","head":["Time","loading","error","notices","What the user sees"],"rows":[["0.0 s (first render)","true","null","[]","\"Loading notices...\""],["2.0 s (answer arrives)","false","null","3 notices","Three cards"]]},{"k":"list","items":[[["Now the same page when the server is stopped:",false]]]},{"k":"table","head":["Time","loading","error","notices","What the user sees"],"rows":[["0.0 s","true","null","[]","\"Loading notices...\""],["0.1 s (connection refused)","false","\"Failed to fetch\"","[]","\"Could not load notices: Failed to fetch\""]]},{"k":"list","items":[[["And when the table is empty:",false]]]},{"k":"table","head":["Time","loading","error","notices","What the user sees"],"rows":[["0.5 s","false","null","[]","\"No notices yet.\""]]},{"k":"list","items":[[["The last two rows differ only in error, and that difference is why you need separate state for it.",false]],[["Without it, a failed request and an empty list would look identical, and the user could not tell whether anything was wrong.",false]]]}],"id":"following-the-three-states-over-time"},{"title":"Reloading and searching","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["To fetch again when something changes, put that thing in the dependency array.",false]]]},{"k":"code","t":"useEffect(() => {\n  // fetch(`/api/notices?search=${search}`) ...\n}, [search]);","lang":"javascript"}],"id":"reloading-and-searching"},{"title":"CORS, briefly","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Your React page runs at localhost:5173 and your API at localhost:3001.",false]],[["Browsers treat different ports as different origins and block the response unless the server allows it.",false]],[["The cors() middleware you installed in Week 6 does that.",false]]]}],"extra":["Next week explains it properly, and shows a cleaner way to avoid it during development."],"id":"cors-briefly"}],"quiz":[{"q":"What does an empty dependency array [] mean?","options":["The effect runs once, right after the first render","The effect runs after each render of the component","The effect never runs, so no side effect is created","The effect runs only when the component is removed"],"answer":0},{"q":"Why can the function passed to useEffect not be async?","options":["It must return nothing or a cleanup function, not a promise","Async functions are blocked by every web browser we have","It would make the component draw twice for every render","Async functions cannot use the fetch function for a call"],"answer":0},{"q":"A component fetches in an effect and calls setNotices with no dependency array. What happens?","options":["It loops, since each state change causes another render","It works well, since the fetch only runs one single time","It fails at once, because React refuses effects without it","It waits until the user clicks, so nothing loops at all"],"answer":0},{"q":"List the three or four states a fetching component should handle.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"What problem does the ignore flag in the cleanup function protect against?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["MDN Contributors. (n.d.). Using the Fetch API. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch","Meta Open Source. (n.d.-a). Synchronizing with effects. React. https://react.dev/learn/synchronizing-with-effects","Meta Open Source. (n.d.-b). You might not need an effect. React. https://react.dev/learn/you-might-not-need-an-effect"],"refsIntro":null,"slideCount":26,"pptx":"downloads/lecture/Week_14_Lecture_React_effects_fetching_loading_and_error.pptx"},{"week":15,"title":"Connecting React to your API","focus":"proxy, CORS and the request lifecycle","duration":"2 hours","file":"Week_15_Lecture_Connecting_React_to_your_API.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can explain why browsers block some requests, connect a React page to your own API without CORS errors, and describe every step of a request from click to screen.",false]]]}],"id":"learning-outcomes"},{"title":"Where we are","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["You have an API backed by PostgreSQL (rebuilt in Week 11, after the MongoDB version of Week 8) and a React interface that can read data from Week 14.",false]],[["Today the two become one app: the page will create, and optionally edit and delete, notices through the API.",false]]]}],"id":"where-we-are"},{"title":"Origins and CORS","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["An origin is the combination of protocol, host and port.",false]],[["Your React page at http://localhost:5173 and your API at http://localhost:3001 have different ports, so they are different origins.",false]]]},{"k":"table","head":["Page origin","API origin","Same origin?"],"rows":[["http://localhost:5173","http://localhost:5173/api","Yes"],["http://localhost:5173","http://localhost:3001/api","No, the port differs"],["https://notices.example.edu.ph","http://notices.example.edu.ph","No, the protocol differs"]]},{"k":"list","items":[[["The cors() middleware makes your server add a header (Access-Control-Allow-Origin) to its responses, which tells the browser \"this origin may read my answer\".",false]],[["For requests that send JSON, the browser first sends a small preflight request using the method OPTIONS to ask permission. cors() answers that too.",false]],[["When CORS is wrong, the browser console shows \"blocked by CORS policy\".",false]]]},{"k":"list","items":[[["Postman never shows this, because CORS is enforced by browsers only.",false]],[["That is one more reason to test the API in Postman first.",false]]]}],"extra":["Browsers apply the same-origin policy: a page may not read responses from another origin unless that server says it is allowed. That permission system is called CORS, Cross-Origin Resource Sharing."],"id":"origins-and-cors"},{"title":"What the browser does with a cross-origin POST","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Your React page is at http://localhost:5173 and calls http://localhost:3001/api/notices directly with a JSON body.",false]]]},{"k":"code","t":"1. Browser -> API   OPTIONS /api/notices\n                    Origin: http://localhost:5173\n                    Access-Control-Request-Method: POST      (the preflight: \"may I?\")\n\n2. API -> Browser   204 No Content\n                    Access-Control-Allow-Origin: http://localhost:5173     (cors() added this)","lang":"javascript"},{"k":"code","t":"3. Browser -> API   POST /api/notices   (the real request)\n\n4. API -> Browser   201 Created   + the Allow-Origin header again","lang":"javascript"},{"k":"list","items":[[["If the server has no cors(), step 2 has no Access-Control-Allow-Origin header, so the browser refuses to run step 3 and prints blocked by CORS policy.",false]],[["Look in the Network tab and you will see only the failed OPTIONS request.",false]]]}],"extra":["The server did nothing wrong, and Postman works fine, because the block is the browser's rule, not the server's."],"id":"what-the-browser-does-with-a-cross-origin-post"},{"title":"A cleaner way in development: the proxy","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Instead of calling http://localhost:3001 from the page, let the Vite dev server forward requests for you.",false]],[["The browser then sees only one origin.",false]]]},{"k":"code","t":"// vite.config.js\nimport { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\nexport default defineConfig({\n  plugins: [react()],\n  server: {","lang":"javascript"},{"k":"code","t":"    port: 5173,\n    proxy: {\n      \"/api\": \"http://localhost:3001\", // forward anything starting with /api\n    },\n  },\n});","lang":"css"},{"k":"callout","t":"Now your React code uses a relative URL."},{"k":"code","t":"fetch(\"/api/notices\"); // no host, no port, no CORS problem","lang":"javascript"},{"k":"callout","t":"The proxy exists only while you develop. When you deploy in Week 17, either one host serves both the page and the API, or the API allows the page's real address explicitly with cors({ origin: \"https://your-site\" })."}],"id":"a-cleaner-way-in-development-the-proxy"},{"title":"The same request with and without the proxy","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"table","head":["","Without the proxy","With the proxy"],"rows":[["Code in React","fetch(\"http://localhost:3001/api/notices\")","fetch(\"/api/notices\")"],["URL the browser requests","http://localhost:3001/api/notices","http://localhost:5173/api/notices"],["Same origin as the page?","No (port differs)","Yes"],["Needs cors() on the server?","Yes","No (Vite forwards it to port 3001 behind the scenes)"],["What the Network tab shows","An OPTIONS preflight, then the POST","Just the POST"]]},{"k":"list","items":[[["Because the code uses a relative URL, the same line also works after deployment, when Express serves both the page and the API from one address.",false]],[["Hard-coding http://localhost:3001 in your React code is the most common reason a deployed page works on the developer's laptop and nowhere else.",false]]]}],"id":"the-same-request-with-and-without-the-proxy"},{"title":"The request lifecycle","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Everything in this course comes together in one round trip.",false]],[["Study this picture until you can redraw it from memory.",false]],[["request lifecycle · 7 steps, browser and server",false]],[["Read it in the order of the numbers.",false]],[["Step 3 is where validation belongs, and step 6 is the one most often forgotten: without it the server has the new notice but the page does not.",false]]]}],"id":"the-request-lifecycle"},{"title":"Posting from React","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Here is the complete submit function.",false]],[["Compare it with the diagram, step by step.",false]]]},{"k":"code","t":"async function handleSubmit(event) {\n  event.preventDefault();\n  setError(\"\");\n  setSubmitting(true);\n  try {\n    const res = await fetch(\"/api/notices\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ title, message }),","lang":"javascript"},{"k":"code","t":"    });\n    const data = await res.json();\n    if (!res.ok) {\n      setError(data.error || \"Something went wrong.\");\n      return;\n    }\n    setNotices((prev) => [data, ...prev]); // use the server's notice, not our own copy\n    setTitle(\"\");\n    setMessage(\"\");\n  } catch {\n    setError(\"Could not reach the server.\");\n  } finally {\n    setSubmitting(false);","lang":"javascript"},{"k":"code","t":"  }\n}","lang":"javascript"},{"k":"callout","t":"Notice what changed from Week 13. The id and the date now come from the server, so the page adds the notice the server returned, not one it made up. A 400 from the server is shown to the user. A network failure is caught separately."}],"id":"posting-from-react"},{"title":"The three outcomes of one submit","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["The user presses \"Post notice\".",false]],[["Walk through the code in the previous example for each case.",false]]]},{"k":"table","head":["Case","What the server sends","What the code does","What the user sees"],"rows":[["Good input","201 and the new notice with a real id","setNotices((prev) => [data, ...prev]), then clears the form","The new card appears at the top"],["Empty title (the page's own check missed it, or someone used Postman)","400 { \"error\": \"Title and message are required.\" }","res.ok is false, so the code reads data.error and calls setError","A red message under the form"],["Server stopped","no answer at all","fetch throws, so the catch block runs","\"Could not reach the server.\""]]},{"k":"list","items":[[["Notice the two different failures.",false]],[["A 400 is the server answering \"no\" (so the page shows the server's own message), while a thrown error means the server never answered (so the page shows a general message).",false]]]}],"extra":["Treating them differently gives the user advice they can act on: fix the form, or try again later."],"id":"the-three-outcomes-of-one-submit"},{"title":"A debugging checklist","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["When something fails, find which side is at fault before changing code.",false]]]},{"k":"table","head":["Symptom","Check first"],"rows":[["Works in Postman but not on the page","The request in the Network tab: URL, method, headers, body"],["\"Blocked by CORS policy\"","cors() on the server, or the proxy in vite.config.js"],["404 on /api/notices","The server is not running, or the route path is wrong"],["req.body is undefined","express.json() missing or registered after the routes"],["Page does not update after POST","You did not call setNotices with the server's reply"]]}],"id":"a-debugging-checklist"},{"title":"Symptom 1: \"I click Post and nothing happens.\"","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Open the Network tab and click the button again.",false]],[["If there is no new request, the problem is in React (the handler is not attached, or preventDefault is missing and the page reloads).",false]]]}],"extra":["\"I click Post and nothing happens.\" Open the Network tab and click the button again. If there is a request with status 400, read its Response tab: the server told you what was wrong."],"id":"symptom-1-i-click-post-and-nothing-happens"},{"title":"Symptom 2: \"The notice is saved but the list does not change.\"","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["The Network tab shows a 201, and psql shows the new row, so the server did its job.",false]],[["The bug is on the page: it never called setNotices with the server's reply.",false]],[["Refreshing the page shows the notice, which confirms it.",false]]]}],"extra":["\"The notice is saved but the list does not change.\" The Network tab shows a 201, and psql shows the new row, so the server did its job."],"id":"symptom-2-the-notice-is-saved-but-the-list-does-"},{"title":"Symptom 3: \"The server prints undefined for req.body.\"","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["The request left the browser with the right JSON (check the Request payload), so look at the server: app.use(express.json()) is missing or sits below the routes.",false]],[["Move it above app.use(\"/api/notices\", ...).",false]],[["The skill in all three is the same: use the Network tab to decide which side is at fault before you change any code.",false]]]}],"extra":["\"The server prints undefined for req.body.\" The request left the browser with the right JSON (check the Request payload), so look at the server:"],"id":"symptom-3-the-server-prints-undefined-for-req-bo"}],"quiz":[{"q":"Which status code should the server return after it creates a new notice?","options":["200, because the request finished without any errors","201, because a new notice was created on the server","204, because the server has no data to send back","302, because the client must go to another address"],"answer":1},{"q":"A POST reaches Express, but req.body is undefined. What is the most likely cause?","options":["The server never registered express.json() before the routes","The browser blocked the request because the body was too big","The notices array was declared with let instead of const","The route path used a capital letter instead of a lowercase one"],"answer":0},{"q":"A POST succeeds, but the new notice only appears after you refresh the page. What did the client most likely forget?","options":["To update the notices state with the notice the server returned","To restart the Express server after saving the route changes","To add a key attribute to the inputs inside the form element","To turn the notice object into a string before it was stored"],"answer":0},{"q":"Why does a request from localhost:5173 to localhost:3001 need CORS, while a request through the Vite proxy does not?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Put these steps in order: the server answers 201, the user clicks Post notice, React re-renders, Express validates and saves, the client calls res.json(), setNotices is called.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["cors. (n.d.). cors [Computer software]. npm. https://www.npmjs.com/package/cors","Google. (n.d.). Network features reference. Chrome for Developers. https://developer.chrome.com/docs/devtools/network/reference","MDN Contributors. (n.d.-a). Cross-Origin Resource Sharing (CORS). MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS","MDN Contributors. (n.d.-b). Same-origin policy. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/Security/Same-origin_policy","Meta Open Source. (n.d.). Updating arrays in state. React. https://react.dev/learn/updating-arrays-in-state","Vite. (n.d.). Server options: server.proxy. https://vite.dev/config/server-options.html#server-proxy"],"refsIntro":null,"slideCount":30,"pptx":"downloads/lecture/Week_15_Lecture_Connecting_React_to_your_API.pptx"},{"week":16,"title":"Authentication and authorization basics","focus":"who are you, and what may you do?","duration":"2 hours","file":"Week_16_Lecture_Authentication_and_authorization_basics.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can explain the difference between authentication and authorization, store passwords safely, issue and check a JSON Web Token, and protect routes on the server and in React.",false]]]}],"id":"learning-outcomes"},{"title":"Two different questions","tag":"CONCEPT","kind":"concept","blocks":[{"k":"table","head":["Term","Question it answers","Example"],"rows":[["Authentication","Who are you?","Logging in with an email and password"],["Authorization","What are you allowed to do?","Only an admin may delete any notice"]]},{"k":"list","items":[[["Two status codes match these. 401 Unauthorized really means \"I do not know who you are\" (not logged in, or a bad token). 403 Forbidden means \"I know who you are, and you are not allowed\".",false]]]}],"id":"two-different-questions"},{"title":"401 or 403?","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Decide the status code for each request, then check the right-hand column.",false]]]},{"k":"table","head":["Request","Status","Why"],"rows":[["POST /api/notices with no Authorization header","401","The server does not know who you are"],["POST /api/notices with a token that expired yesterday","401","The token can no longer prove who you are"],["POST /api/notices with a valid student token","201","Known and allowed"],["DELETE /api/notices/3 with a valid student token","403","The server knows who you are, and students may not delete"]]},{"k":"table","head":["Request","Status","Why"],"rows":[["DELETE /api/notices/3 with a valid admin token","204","Known and allowed"],["POST /api/auth/login with the wrong password","401","The credentials did not prove identity"]]},{"k":"list","items":[[["The rule of thumb: 401 = \"log in first\", and 403 = \"you are logged in, but not allowed\".",false]]]}],"id":"401-or-403"},{"title":"Never store passwords","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["If your database leaked and held real passwords, every user would be at risk, especially because many people reuse passwords.",false]],[["Instead you store a hash: a one-way scramble.",false]],[["You cannot turn a hash back into the password, but you can hash a login attempt and compare.",false]]]},{"k":"code","t":"npm install bcryptjs jsonwebtoken","lang":"bash"},{"k":"code","t":"const bcrypt = require(\"bcryptjs\");\n\nconst passwordHash = await bcrypt.hash(\"correct horse battery\", 10); // 10 = work factor\nconst ok = await bcrypt.compare(\"correct horse battery\", passwordHash); // true","lang":"javascript"},{"k":"callout","t":"Never write your own encryption or hashing. Use well-tested libraries."}],"extra":["A good hashing library adds a random salt and is deliberately slow, which makes guessing expensive."],"id":"never-store-passwords"},{"title":"What a password hash looks like","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"code","t":"const bcrypt = require(\"bcryptjs\");\n\nconst hash = await bcrypt.hash(\"password123\", 10);\nconsole.log(hash);\n// $2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy   (yours will differ)\n\nconsole.log(await bcrypt.compare(\"password123\", hash)); // true\nconsole.log(await bcrypt.compare(\"Password123\", hash)); // false\n\nconst hash2 = await bcrypt.hash(\"password123\", 10);\nconsole.log(hash2 === hash); // false, because each hash uses a fresh random salt","lang":"javascript"},{"k":"list","items":[[["Three facts to notice.",false]],[["The text starts with $2a$10$, which records the algorithm and the cost (10).",false]],[["The same password gives a different hash every time because of the random salt, so you can never compare hashes with === and must use bcrypt.compare.",false]]]}],"extra":["And nobody, including you, can turn the hash back into the password, so if a user forgets it, the only option is to set a new one."],"id":"what-a-password-hash-looks-like"},{"title":"Tokens","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["After login, the server needs a way to recognise the same user on later requests, because HTTP remembers nothing.",false]],[["A JSON Web Token (JWT) is a signed string the server gives the user.",false]]]}],"extra":["It has three parts separated by dots: a header, a payload (such as the user's id and role), and a signature made with a secret only the server knows. Anyone can read the payload, but nobody can change it without breaking the signature. So never put secrets in it."],"id":"tokens"},{"title":"Opening up a token","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["A token looks like three pieces joined by dots:",false]]]},{"k":"code","t":"eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOjEyLCJyb2xlIjoic3R1ZGVudCIsImV4cCI6MTc2MDYwMDAwMH0.k3Jd8...\n   header                 payload                                            signature","lang":"text"},{"k":"callout","t":"The first two pieces are only encoded, not secret. Paste the middle piece into atob(...) in the browser console, or into a decoder, and you see:"},{"k":"code","t":"{ \"sub\": 12, \"role\": \"student\", \"exp\": 1760600000 }","lang":"json"},{"k":"list","items":[[["That reads: user 12, role student, expires at that time.",false]],[["The server created the signature using JWT_SECRET.",false]],[["If you change \"student\" to \"admin\" in the payload, the signature no longer matches, jwt.verify throws, and the middleware answers 401.",false]],[["The flow is:",false]]]},{"k":"list","items":[[["The user sends an email and password to POST /api/auth/login.",false]],[["The server checks the password hash and replies with a token.",false]],[["The page stores the token and sends it with each request in the header Authorization: Bearer <token>.",false]],[["Middleware on the server verifies the token and attaches the user to req.",false]],[["Protected routes run only if verification passed.",false]]]}],"extra":["So a user can read their token but cannot forge one, which is why the payload may hold an id and a role but never a password."],"id":"opening-up-a-token"},{"title":"The users table, the user model and the auth controller","tag":"CONCEPT","kind":"concept","blocks":[{"k":"code","t":"-- db/users.sql: run once in psql\nCREATE TABLE users (\n  id            SERIAL PRIMARY KEY,\n  name          TEXT NOT NULL,\n  email         TEXT NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  role          TEXT NOT NULL DEFAULT 'student' CHECK (role IN ('student', 'admin')),\n  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- record who posted each notice: a foreign key to users\nALTER TABLE notices ADD COLUMN author_id INTEGER REFERENCES users(id);","lang":"javascript"},{"k":"code","t":"// models/userModel.js\nconst db = require(\"../db\");\n\nexports.findByEmail = async (email) => {\n  const { rows } = await db.query(\"SELECT * FROM users WHERE email = $1\", [email.toLowerCase()]);\n  return rows[0]; // undefined when there is no such user\n};\n\nexports.create = async ({ name, email, passwordHash }) => {\n  const { rows } = await db.query(\n    `INSERT INTO users (name, email, password_hash)\n     VALUES ($1, $2, $3)\n     RETURNING id, name, email, role`,","lang":"javascript"},{"k":"code","t":"    [name, email.toLowerCase(), passwordHash]\n  );\n  return rows[0];\n};","lang":"javascript"},{"k":"code","t":"// controllers/authController.js\nconst bcrypt = require(\"bcryptjs\");\nconst jwt = require(\"jsonwebtoken\");\nconst User = require(\"../models/userModel\");\nconst asyncHandler = require(\"../middleware/asyncHandler\");\n\nfunction signToken(user) {\n  return jwt.sign(","lang":"javascript"},{"k":"code","t":"    { sub: String(user.id), role: user.role },\n    process.env.JWT_SECRET,\n    { expiresIn: \"2h\" }\n  );\n}\n\nfunction publicUser(user) {\n  return { id: user.id, name: user.name, email: user.email, role: user.role };\n}\n\nexports.register = asyncHandler(async (req, res) => {\n  const { name, email, password } = req.body;\n  if (!name || !email || !password || password.length < 8) {","lang":"javascript"},{"k":"code","t":"    return res.status(400).json({ error: \"Name, email and a password of 8 or more characters are required.\" });\n  }\n  if (await User.findByEmail(email)) {\n    return res.status(409).json({ error: \"That email is already registered.\" });\n  }\n  const passwordHash = await bcrypt.hash(password, 10);\n  const user = await User.create({ name, email, passwordHash });\n  res.status(201).json({ token: signToken(user), user: publicUser(user) });\n});\n\nexports.login = asyncHandler(async (req, res) => {","lang":"javascript"},{"k":"code","t":"  const { email, password } = req.body;\n  const user = email && (await User.findByEmail(email));\n  const ok = user && password && (await bcrypt.compare(password, user.password_hash));\n  if (!ok) {\n    // the same message for both cases, so attackers cannot tell which part was wrong\n    return res.status(401).json({ error: \"Invalid email or password.\" });\n  }\n  res.json({ token: signToken(user), user: publicUser(user) });\n});","lang":"javascript"},{"k":"callout","t":"Put the secret in .env, for example JWT_SECRET= followed by a long random string, and never commit it."}],"id":"the-users-table-the-user-model-and-the-auth-cont"},{"title":"Middleware that protects routes","tag":"CONCEPT","kind":"concept","blocks":[{"k":"code","t":"// middleware/auth.js\nconst jwt = require(\"jsonwebtoken\");\n\nexports.requireAuth = (req, res, next) => {\n  const [type, token] = (req.headers.authorization || \"\").split(\" \");\n  if (type !== \"Bearer\" || !token) {\n    return res.status(401).json({ error: \"Please log in.\" });\n  }\n  try {\n    const payload = jwt.verify(token, process.env.JWT_SECRET);\n    req.user = { id: payload.sub, role: payload.role };\n    next();\n  } catch {","lang":"javascript"},{"k":"code","t":"    res.status(401).json({ error: \"Your session is invalid or has expired.\" });\n  }\n};\n\nexports.requireRole = (role) => (req, res, next) =>\n  req.user && req.user.role === role\n    ? next()\n    : res.status(403).json({ error: \"You are not allowed to do that.\" });","lang":"javascript"},{"k":"code","t":"// routes/notices.js\nrouter.get(\"/\", c.getNotices);                                    // anyone may read\nrouter.post(\"/\", requireAuth, c.createNotice);                   // must be logged in\nrouter.delete(\"/:id\", requireAuth, requireRole(\"admin\"), c.deleteNotice); // admins only","lang":"javascript"},{"k":"callout","t":"In createNotice, record who posted. The ALTER TABLE above added author_id, a foreign key: the database will only accept an id that really exists in users, and refuses anything else with error 23503. Save it as a fourth value, req.user.id, in the same parameterized INSERT:"},{"k":"code","t":"const { rows } = await db.query(\n  `INSERT INTO notices (title, message, category, author_id)\n   VALUES ($1, $2, $3, $4)\n   RETURNING ${COLUMNS}`,\n  [title.trim(), message.trim(), category, req.user.id]\n);","lang":"javascript"},{"k":"list","items":[[["The register controller checks for a duplicate email and then inserts, which leaves a tiny gap if two people register at the same moment.",false]]]}],"extra":["The UNIQUE rule on users.email closes it: the second insert fails with error 23505, and your central error handler from Week 11 turns that into a 409. Rely on the database for rules that must never be broken."],"id":"middleware-that-protects-routes"},{"title":"One login, from click to protected request","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"table","head":["Step","Who","What happens"],"rows":[["1","User","Types email and password in the form and presses Log in"],["2","React","POST /api/auth/login with { email, password }"],["3","Server","Finds the user, runs bcrypt.compare, signs a token with { sub, role } and expiresIn: \"2h\""],["4","Server","Answers 200 { token, user }"],["5","React","Saves the token in localStorage and in state, so the post form appears"],["6","User","Posts a notice"],["7","React","POST /api/notices with the header Authorization: Bearer <token>"],["8","Server","requireAuth verifies the token and sets req.user, then the controller saves the notice with author_id = req.user.id"],["9","Server","Answers 201"]]},{"k":"list","items":[[["Two hours later the token expires.",false]],[["Step 8 now fails with 401, React sees the 401, calls handleLogout(), and the user is shown the login form again.",false]],[["Nothing was broken: the system behaved exactly as designed.",false]]]}],"id":"one-login-from-click-to-protected-request"},{"title":"Authentication in React","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["The page keeps the token in state, saves it so it survives a refresh, and sends it with protected requests.",false]]]},{"k":"code","t":"const [token, setToken] = useState(() => localStorage.getItem(\"token\"));\n\nfunction handleLogin({ token }) {\n  localStorage.setItem(\"token\", token);\n  setToken(token);\n}\n\nfunction handleLogout() {\n  localStorage.removeItem(\"token\");","lang":"javascript"},{"k":"code","t":"  setToken(null);\n}\n\n// when posting\nconst res = await fetch(\"/api/notices\", {\n  method: \"POST\",\n  headers: {\n    \"Content-Type\": \"application/json\",\n    Authorization: `Bearer ${token}`,\n  },\n  body: JSON.stringify({ title, message }),\n});\nif (res.status === 401) handleLogout(); // the session expired","lang":"javascript"},{"k":"callout","t":"Show the post form only when token exists, and a login form otherwise. Hiding a button is for convenience only. The real protection is on the server, because anyone can call your API without your page."}],"id":"authentication-in-react"},{"title":"Security notes to remember","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Use HTTPS in production, or tokens and passwords travel in the clear.",false]],[["Keep tokens short-lived. Storing a token in localStorage is simple but can be stolen if an attacker injects script into your page. Many production apps use secure, httpOnly cookies instead. You will compare the two in the challenge problem.",false]],[["Never log passwords or tokens, and never return password_hash in a response.",false]]]}],"id":"security-notes-to-remember"}],"quiz":[{"q":"A user is logged in but tries to delete a notice that only admins may delete. Which status code fits?","options":["403, because the person is known and is not allowed","401, because the person is not known to the server","404, because the person cannot find the notice route","400, because the person has sent the wrong sort of data"],"answer":0},{"q":"Why do we store a password hash and not the password?","options":["A leaked database would not reveal the real passwords","A hash takes up much less space than the password does","A hash lets us show users their password if they forget","A hash is needed because PostgreSQL cannot store text"],"answer":0},{"q":"Why does the login route return the same message for an unknown email and a wrong password?","options":["So attackers cannot tell which of the two parts was wrong","So the server can answer the request a bit more quickly","So the page can use a single component to show the error","So that fewer lines of code are needed inside the route"],"answer":0},{"q":"Why is hiding the \"Delete\" button in React not enough to protect the route?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"What are the three parts of a JWT, and which part must never contain a secret?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Auth0. (n.d.). Introduction to JSON Web Tokens. JWT.IO. https://jwt.io/introduction","bcryptjs. (n.d.). bcryptjs [Computer software]. npm. https://www.npmjs.com/package/bcryptjs","jsonwebtoken. (n.d.). jsonwebtoken [Computer software]. npm. https://www.npmjs.com/package/jsonwebtoken","MDN Contributors. (n.d.-a). 401 Unauthorized. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/401","MDN Contributors. (n.d.-b). 403 Forbidden. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/403","MDN Contributors. (n.d.-c). HTTP authentication. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Web/HTTP/Authentication","OWASP Foundation. (n.d.-a). Authentication cheat sheet. OWASP Cheat Sheet Series. https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html","OWASP Foundation. (n.d.-b). JSON Web Token for Java cheat sheet. OWASP Cheat Sheet Series. https://cheatsheetseries.owasp.org/cheatsheets/JSON_Web_Token_for_Java_Cheat_Sheet.html","OWASP Foundation. (n.d.-c). Password storage cheat sheet. OWASP Cheat Sheet Series. https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html","PostgreSQL Global Development Group. (n.d.). Constraints: Foreign keys. In PostgreSQL documentation. https://www.postgresql.org/docs/current/ddl-constraints.html#DDL-CONSTRAINTS-FK"],"refsIntro":null,"slideCount":38,"pptx":"downloads/lecture/Week_16_Lecture_Authentication_and_authorization_basics.pptx"},{"week":17,"title":"Testing, environment variables and deployment","focus":"making the app trustworthy and putting it online","duration":"2 hours","file":"Week_17_Lecture_Testing_environment_variables_and_deploy.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["By the end of this lecture you can write automated tests for your API, keep configuration in environment variables, build the React app for production, and deploy the whole project.",false]]]}],"id":"learning-outcomes"},{"title":"Why automate tests","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Testing in Postman by hand works, but you will not repeat 30 requests after every change.",false]],[["An automated test runs the same checks in seconds and tells you the moment you break something.",false]],[["Tests are also living documentation of what your API promises.",false]]]}],"id":"why-automate-tests"},{"title":"A unit test and an integration test side by side","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["A unit test checks one function on its own, with no server and no database:",false]]]},{"k":"code","t":"const { validateNotice } = require(\"../validate\");\n\ntest(\"rejects an empty title\", () => {\n  expect(validateNotice({ title: \"  \", message: \"Hi\" })).toBe(\"Title is required.\");\n});\n\ntest(\"accepts a good notice\", () => {\n  expect(validateNotice({ title: \"Hello\", message: \"World\" })).toBeNull();","lang":"javascript"},{"k":"code","t":"});","lang":"text"},{"k":"callout","t":"An integration test sends a real request through the routes, the middleware and the database:"},{"k":"code","t":"test(\"POST /api/notices with no title returns 400\", async () => {\n  const res = await request(app)\n    .post(\"/api/notices\")\n    .set(\"Authorization\", `Bearer ${token}`)\n    .send({ title: \"\", message: \"Hi\" });\n  expect(res.status).toBe(400);\n});","lang":"javascript"},{"k":"callout","t":"If the unit test fails, you know the bug is inside validateNotice. If only the integration test fails, the function is fine and the problem is in how the pieces connect (a missing middleware, a wrong route, a bad query). That is why you want both kinds."},{"k":"list","items":[[["Three kinds of tests are worth knowing:",false]]]},{"k":"table","head":["Kind","What it checks","Speed"],"rows":[["Unit","One function on its own, such as validateNotice","Very fast"],["Integration","Several parts together, such as a route, validation and the database","Fast"],["End to end","The whole app through a real browser","Slow"]]},{"k":"list","items":[[["In this course we write integration tests for the API with Jest (the test runner) and Supertest (which calls your Express app without starting a real server).",false]]]},{"k":"code","t":"npm install --save-dev jest supertest","lang":"bash"},{"k":"code","t":"\"scripts\": {\n  \"test\": \"jest --runInBand\"\n}","lang":"javascript"},{"k":"callout","t":"For this to work, app.js must export the Express app, and server.js must be the file that connects to the database and calls listen. You set up that split in Week 8."},{"k":"list","items":[[["First, teach db.js to pick the test database.",false]],[["Jest sets NODE_ENV to test for you, so no extra setup is needed.",false]],[["The ssl line is for hosted databases, which usually require an encrypted connection.",false]]]},{"k":"code","t":"// db.js\nrequire(\"dotenv\").config();\nconst { Pool } = require(\"pg\");\n\nconst isTest = process.env.NODE_ENV === \"test\";\n\nconst pool = new Pool({\n  connectionString: isTest ? process.env.DATABASE_TEST_URL : process.env.DATABASE_URL,\n  ssl: process.env.NODE_ENV === \"production\" ? { rejectUnauthorized: false } : false,\n});\n\nmodule.exports = {","lang":"javascript"},{"k":"code","t":"  query: (text, params) => pool.query(text, params),\n  pool,\n};","lang":"javascript"},{"k":"callout","t":"Then write the tests. Instead of deleteMany, one TRUNCATE statement empties both tables and restarts the id counters, so every test begins from the same known state."},{"k":"code","t":"// tests/notices.test.js\nconst request = require(\"supertest\");\nconst app = require(\"../app\");\nconst db = require(\"../db\");","lang":"javascript"},{"k":"code","t":"let token;\n\nbeforeEach(async () => {\n  await db.query(\"TRUNCATE notices, users RESTART IDENTITY CASCADE\");\n  const body = { name: \"Test\", email: \"test@example.com\", password: \"password123\" };\n  const res = await request(app).post(\"/api/auth/register\").send(body);\n  token = res.body.token;\n});\n\nafterAll(async () => {\n  await db.pool.end(); // lets Jest exit cleanly\n});","lang":"javascript"},{"k":"code","t":"describe(\"POST /api/notices\", () => {\n  test(\"creates a notice and returns 201\", async () => {\n    const res = await request(app)\n      .post(\"/api/notices\")\n      .set(\"Authorization\", `Bearer ${token}`)\n      .send({ title: \"Hello\", message: \"World\" });\n\n    expect(res.status).toBe(201);\n    expect(res.body.title).toBe(\"Hello\");\n  });\n\n  test(\"rejects an empty title with 400\", async () => {\n    const res = await request(app)\n      .post(\"/api/notices\")","lang":"javascript"},{"k":"code","t":"      .set(\"Authorization\", `Bearer ${token}`)\n      .send({ title: \"\", message: \"World\" });\n\n    expect(res.status).toBe(400);\n    expect(res.body.error).toBeDefined();\n  });\n\n  test(\"rejects a request with no token with 401\", async () => {\n    const res = await request(app).post(\"/api/notices\").send({ title: \"Hi\", message: \"There\" });\n    expect(res.status).toBe(401);\n  });\n});","lang":"javascript"}],"id":"a-unit-test-and-an-integration-test-side-by-side"},{"title":"Reading a failing test","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["Suppose someone changes the controller so an empty title returns 200 instead of 400.",false]],[["Running npm test prints something like:",false]]]},{"k":"code","t":" FAIL  tests/notices.test.js\n  POST /api/notices\n    ✓ creates a notice and returns 201 (48 ms)\n    ✕ rejects an empty title with 400 (21 ms)\n\n  ● POST /api/notices › rejects an empty title with 400","lang":"javascript"},{"k":"code","t":"    expect(received).toBe(expected)\n\n    Expected: 400\n    Received: 200\n\n      27 |       .send({ title: \"\", message: \"World\" });\n    > 28 |     expect(res.status).toBe(400);","lang":"javascript"},{"k":"list","items":[[["Read it from the top: which test failed (the name reads like a sentence), what was expected (400), what was received (200), and the exact line (28).",false]]]},{"k":"list","items":[[["Three habits make tests trustworthy.",false]],[["Use a separate test database, because the tests delete data.",false]],[["Start each test from a known state with beforeEach.",false]]]}],"extra":["The test just told you that the validation no longer works, and you found out in seconds instead of when a user complained. Undo the change and the test turns green again.","Test the failures as carefully as the successes. A good test name reads like a sentence."],"id":"reading-a-failing-test"},{"title":"Environment variables","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Settings that change between your laptop and the live server, such as the database address, the secret and the allowed website, must not be written in the code.",false]],[["Put them in the environment.",false]]]},{"k":"table","head":["Variable","Example","Used for"],"rows":[["PORT","3001","The port the server listens on (hosts set this for you)"],["DATABASE_URL","postgres://user:pass@host:5432/db","The production database"]]},{"k":"table","head":["Variable","Example","Used for"],"rows":[["DATABASE_TEST_URL","postgres://postgres:pass@localhost:5432/campus_notices_test","The test database"],["JWT_SECRET","a long random string","Signing tokens"],["CLIENT_URL","https://notices.example.edu.ph","The one website allowed by CORS"]]},{"k":"list","items":[[["Read them with process.env.NAME.",false]],[["Commit a .env.example file that lists the names with fake values, and keep the real .env out of Git.",false]]]},{"k":"list","items":[[["The database address is the most important setting of all, and in PostgreSQL it is one string: postgres://user:password@host:5432/database.",false]],[["Your laptop, your test database and the live server each get a different one.",false]]]}],"extra":["Hosted databases usually insist on an encrypted connection, which is what the ssl option in db.js is for. Never put this string in the code, because it contains the password."],"id":"environment-variables"},{"title":"Building the React app","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Vite can turn your project into plain files the browser can run anywhere.",false]]]},{"k":"code","t":"cd client\nnpm run build   # creates client/dist with index.html and bundled assets","lang":"bash"}],"id":"building-the-react-app"},{"title":"One setting, three environments","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["The code never changes.",false]],[["Only the environment does.",false]]]},{"k":"code","t":"const PORT = process.env.PORT || 3001;\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL });","lang":"javascript"},{"k":"table","head":["Where it runs","PORT","DATABASE_URL points to"],"rows":[["Your laptop","not set, so 3001","postgres://postgres:pw@localhost:5432/campus_notices"],["Tests (NODE_ENV=test)","not set, so 3001","the test database campus_notices_test (chosen in db.js)"],["The live host","set by the host, such as 10000","the hosted database's own address"]]},{"k":"list","items":[[["If a value were written in the code instead, you would have to edit and re-test the code for every place it runs, and a password would sit in your repository for anyone to read.",false]],[["With environment variables you change a setting in a dashboard and restart.",false]]]}],"extra":["If your live site shows ECONNREFUSED 127.0.0.1:5432, the host has no DATABASE_URL, so the app fell back to a database on localhost that does not exist there."],"id":"one-setting-three-environments"},{"title":"Deployment: one host serving everything","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["The simplest design for a class project is to let Express serve the built React files as well as the API, so there is one origin and no CORS problem.",false]]]},{"k":"code","t":"// app.js (add after the API routes, before the error handler)\nconst path = require(\"path\");\n\nif (process.env.NODE_ENV === \"production\") {\n  const dist = path.join(__dirname, \"../client/dist\");\n  app.use(express.static(dist));\n  app.get(\"*\", (req, res) => res.sendFile(path.join(dist, \"index.html\")));\n}","lang":"javascript"},{"k":"callout","t":"A small package.json at the project root can give a host one build command and one start command."},{"k":"code","t":"{\n  \"scripts\": {\n    \"build\": \"npm --prefix client install && npm --prefix client run build && npm --prefix server install\",\n    \"start\": \"node server/server.js\"\n  }\n}","lang":"json"}],"id":"deployment-one-host-serving-everything"},{"title":"How one Express app answers the page and the API","tag":"WORKED EXAMPLE","kind":"example","blocks":[{"k":"list","items":[[["In production the same server receives every kind of request.",false]],[["Express checks routes from top to bottom:",false]]]},{"k":"table","head":["Request","Matched by","Result"],"rows":[["GET /api/notices","The API router","JSON"],["GET /api/health","The health route","{ \"status\": \"ok\" }"],["GET /assets/index-a1b2c3.js","express.static(\"client/dist\")","The built JavaScript file"],["GET /","express.static finds index.html","The React page"],["GET /notices/5 (a page route inside React)","The catch-all that sends index.html","The React page, which then draws the right view"],["GET /api/nope","The /api 404 handler","JSON 404"]]},{"k":"list","items":[[["The order matters.",false]],[["If the catch-all sat above the API routes, GET /api/notices would return the HTML page instead of JSON, and your React code would fail with Unexpected token '<' when it tried to read it as JSON.",false]]]}],"extra":["That exact error message is the signature of an API request that accidentally received the HTML page, so keep the catch-all last."],"id":"how-one-express-app-answers-the-page-and-the-api"},{"title":"A deployment checklist","tag":"CONCEPT","kind":"concept","blocks":[{"k":"table","head":["Step","Check"],"rows":[["1","The code is on GitHub, with node_modules, .env and dist ignored"],["2","The database is a hosted one, such as the PostgreSQL service of your host or a free provider like Neon or Supabase, you have run your schema files on it, and its connection string is set as DATABASE_URL"],["3","The host has your environment variables set in its dashboard"],["4","The build command and the start command are set"],["5","NODE_ENV is production"],["6","You open the live address and try every feature, with the Network tab open"],["7","You add a GET /api/health route that the host or you can use to check the app is alive"]]},{"k":"list","items":[[["Free hosting plans and their limits change often.",false]],[["Check the current options (for example Render, Railway or Fly.io) before the lab, and expect a free app to sleep after being idle, so the first request may be slow.",false]]]}],"id":"a-deployment-checklist"}],"quiz":[{"q":"Why do tests use a separate database?","options":["Tests delete data, and they must never touch real data","Jest can only connect to a database that has a test name","A separate database makes every test run in less time","PostgreSQL refuses to save data when a test is running now"],"answer":0},{"q":"Why is app.js kept apart from server.js?","options":["Tests can import the app without starting a live server","Express can only work when there are two separate files","The host needs two files to be able to deploy an app","The split makes the server restart every time it is saved"],"answer":0},{"q":"Which of these belongs in an environment variable?","options":["The secret used to sign tokens, which differs for each host","The route path for the notices, which is the same for all","The title that is shown at the top of the page for users","The list of fields that every notice is made to contain"],"answer":0},{"q":"What does npm run build produce, and where do the files go?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"Why should you also write tests for failures, such as a 401 or a 400?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Express. (n.d.-a). Production best practices: Performance and reliability. https://expressjs.com/en/advanced/best-practice-performance.html","Express. (n.d.-b). Production best practices: Security. https://expressjs.com/en/advanced/best-practice-security.html","Fly.io. (n.d.). Fly.io docs. https://fly.io/docs/","GitHub. (n.d.). About Git. GitHub Docs. https://docs.github.com/en/get-started/using-git/about-git","Jest. (n.d.-a). Expect. https://jestjs.io/docs/expect","Jest. (n.d.-b). Getting started. https://jestjs.io/docs/getting-started","ladjs. (n.d.). supertest [Computer software]. GitHub. https://github.com/ladjs/supertest","Neon. (n.d.). Neon docs. https://neon.com/docs","Railway. (n.d.). Railway docs. https://docs.railway.com/","Render. (n.d.). Render docs. https://render.com/docs","Supabase. (n.d.). Supabase docs. https://supabase.com/docs","Vite. (n.d.-a). Building for production. https://vite.dev/guide/build.html","Vite. (n.d.-b). Deploying a static site. https://vite.dev/guide/static-deploy.html","Wiggins, A. (2017). III. Config. In The twelve-factor app. https://12factor.net/config"],"refsIntro":null,"slideCount":37,"pptx":"downloads/lecture/Week_17_Lecture_Testing_environment_variables_and_deploy.pptx"},{"week":18,"title":"Final project presentations and demos","focus":"presentations","duration":"2 hours","file":"Week_18_Lecture_Final_project_presentations_and_demos.pptx","sections":[{"title":"Learning outcomes","tag":"LECTURE","kind":"outcomes","blocks":[{"k":"list","items":[[["This week you show what you built.",false]],[["A good presentation does three things: it explains the problem, shows the product working, and shows that you understand how it works underneath.",false]]]}],"id":"learning-outcomes"},{"title":"Suggested format for each team","tag":"CONCEPT","kind":"concept","blocks":[{"k":"table","head":["Part","Time","What to cover"],"rows":[["Problem and users","1 min","Who needs this, and what hurts today"],["Architecture","2 min","One diagram: React, Express, PostgreSQL, and where authentication sits"],["Live demo","3 min","The main user journey, from start to finish"],["Hard parts","1 min","One problem you hit and how you solved it"],["Lessons and next steps","1 min","What you would do with two more weeks"],["Questions","4 min","The audience and instructor ask"]]},{"k":"list","items":[[["The times above total 12 minutes per team.",false]]]},{"k":"list","items":[[["Adjust them to the number of teams in your class and keep a strict timekeeper.",false]]]}],"id":"suggested-format-for-each-team"},{"title":"Tips for a clear demo","tag":"CONCEPT","kind":"concept","blocks":[{"k":"list","items":[[["Open the app and sign in before you start, and keep the Network tab ready to show a real request.",false]],[["Rehearse one path that you know works. Do not improvise on stage.",false]],[["Prepare a fallback: a short screen recording or screenshots, in case the network or the host fails.",false]],[["Speak about decisions: why this schema, why these status codes, why protect this route.",false]],[["Everybody on the team speaks.",false]]]}],"id":"tips-for-a-clear-demo"},{"title":"Submit before the session","tag":"CONCEPT","kind":"concept","blocks":[{"k":"table","head":["Item","Requirement"],"rows":[["Repository link","Clean history, node_modules, .env and dist ignored"],["README.md","What it is, how to run it, the environment variables it needs, and the routes it offers"],[".env.example","Variable names with fake values, and no real secrets"],["Live URL","Or a recorded demo if hosting was not possible"],["API collection","A Postman collection with success and failure cases"],["Test results","A screenshot of your passing tests"]]}],"id":"submit-before-the-session"}],"quiz":[{"q":"Your live demo fails because the host is down. What do you do?","options":["Switch calmly to the recording and explain what is shown","Wait for the host to come back while the class waits too","Skip the demo and read through all of the code one line at a time","Ask the instructor to move the team to the end of the session"],"answer":0},{"q":"Which item must never appear in your repository?","options":["The real .env file that holds your secret and database URL","The .env.example file that holds only fake example values","The README file that explains how to run the project now","The package.json file that lists the scripts and packages"],"answer":0},{"q":"What is the best use of your architecture slide?","options":["To show how the parts connect and where each request goes","To list every file name that is in the project folder tree","To show the colours and fonts that the interface is using","To repeat the text of the README in a different layout"],"answer":0},{"q":"Name two design decisions you made in this project and explain why you made each.","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."},{"q":"What would you test first if you had one more hour, and why?","open":true,"hint":"Write your answer in your notebook, then compare with a classmate."}],"refs":["Express. (n.d.). Express: Fast, unopinionated, minimalist web framework for Node.js. https://expressjs.com/","GitHub. (n.d.). About READMEs. GitHub Docs. https://docs.github.com/en/repositories/managing-your-repository-settings-and-features/customizing-your-repository/about-readmes","Google. (n.d.). Learn. web.dev. https://web.dev/learn","MDN Contributors. (n.d.). Accessibility. MDN Web Docs. https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Accessibility","Meta Open Source. (n.d.). React. https://react.dev/","node-postgres. (n.d.). node-postgres. https://node-postgres.com/","OWASP Foundation. (n.d.). OWASP top ten. https://owasp.org/www-project-top-ten/","PostgreSQL Global Development Group. (n.d.). PostgreSQL documentation. https://www.postgresql.org/docs/current/"],"refsIntro":null,"slideCount":13,"pptx":"downloads/lecture/Week_18_Lecture_Final_project_presentations_and_demos.pptx"}];